:root {
  --bg: #f3f7fb;
  --surface: #ffffff;
  --surface-soft: #f2f3ff;
  --surface-muted: #eef2f7;
  --surface-border: #d8e6f2;
  --text: #131b2e;
  --text-primary: #131b2e;
  --text-muted: #071832;
  --text-soft: #53677f;
  --primary: #052a6b;
  --secondary: #0759d6;
  --secondary-soft: #00bfe5;
  --secondary-pale: #eaf4ff;
  --qori-panel: #052a6b;
  --danger: #c62828;
  --shadow: 0 18px 36px rgba(19, 27, 46, 0.06);
  --radius: 12px;
  --sidebar-width: 276px;
  --topbar-height: 72px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: "Inter", sans-serif;
  overflow-x: hidden;
}

button,
input,
table,
select,
textarea {
  font: inherit;
}

.material-symbols-outlined {
  font-variation-settings: "FILL" 0, "wght" 400, "GRAD" 0, "opsz" 24;
}

.hidden {
  display: none !important;
}

.portal-shell {
  min-height: 100vh;
}

.login-screen {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background:
    radial-gradient(circle at top left, rgba(0, 191, 229, 0.12), transparent 28%),
    linear-gradient(180deg, #f8fbff 0%, #eef6ff 100%);
}

.login-card {
  width: min(100%, 460px);
  background: var(--surface);
  border: 1px solid var(--surface-border);
  border-radius: 18px;
  box-shadow: var(--shadow);
  padding: 28px;
}

.login-brand,
.sidebar-brand {
  display: flex;
  gap: 12px;
  align-items: center;
}

.brand-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  color: var(--primary);
  background: rgba(0, 191, 229, 0.18);
}

.brand-logo {
  object-fit: contain;
  padding: 3px;
}

.nav-link-button {
  min-height: 38px;
  padding: 0 12px;
  white-space: nowrap;
}

.login-brand h1,
.sidebar-brand h1 {
  margin: 0;
  font-size: 18px;
  line-height: 1.1;
  font-weight: 800;
  color: var(--primary);
}

.login-brand p,
.sidebar-brand p {
  margin: 4px 0 0;
  color: var(--text-muted);
  font-size: 13px;
}

.login-copy {
  margin: 28px 0 20px;
}

.login-copy h2 {
  margin: 0 0 8px;
  font-size: 32px;
  line-height: 1.1;
}

.login-copy p,
.view-head p,
.placeholder-card p,
.map-card p {
  margin: 0;
  color: var(--text-muted);
}

.gaming-core-entry {
  width: 100%;
  min-height: 136px;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  appearance: none;
  border: 2px solid #f8d66d;
  border-radius: 18px;
  display: grid;
  grid-template-columns: 78px minmax(0, 1fr) 54px;
  align-items: center;
  gap: 22px;
  padding: 28px 30px;
  text-align: left;
  cursor: pointer;
  background:
    linear-gradient(90deg, #f8d66d 0 9px, transparent 9px),
    linear-gradient(135deg, #020617 0%, #052a6b 42%, #00bfe5 72%, #075985 100%);
  color: #fff;
  box-shadow:
    0 0 0 4px rgba(248, 214, 109, 0.16),
    0 28px 70px rgba(5, 42, 107, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease, background 0.18s ease;
}

.gaming-core-entry > * {
  position: relative;
  z-index: 1;
}

.gaming-core-entry::after {
  content: "ACTIVA Y VENDE";
  position: absolute;
  z-index: 2;
  top: 16px;
  right: 18px;
  padding: 6px 10px;
  border-radius: 999px;
  background: #f8d66d;
  color: #071832;
  font-family: "JetBrains Mono", monospace;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0;
}

.gaming-core-entry:hover,
.gaming-core-entry:focus-visible {
  transform: translateY(-3px);
  border-color: #ffffff;
  box-shadow:
    0 0 0 5px rgba(248, 214, 109, 0.22),
    0 34px 82px rgba(5, 42, 107, 0.48),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
  outline: none;
}

.gaming-core-entry:focus-visible {
  box-shadow:
    0 0 0 5px rgba(248, 214, 109, 0.62),
    0 34px 82px rgba(5, 42, 107, 0.48);
}

.gaming-core-entry .material-symbols-outlined:first-child {
  width: 78px;
  height: 78px;
  border-radius: 18px;
  display: grid;
  place-items: center;
  background: #eaf4ff;
  color: #052a6b;
  font-size: 46px;
  box-shadow: inset 0 0 0 1px rgba(5, 42, 107, 0.08);
}

.gaming-core-entry .material-symbols-outlined:last-child {
  justify-self: end;
  align-self: center;
  width: 54px;
  height: 54px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.18);
  color: #ffffff;
  font-size: 34px;
}

.gaming-core-entry strong,
.gaming-core-entry small {
  display: block;
}

.gaming-core-entry strong {
  max-width: 24ch;
  font-size: clamp(28px, 3vw, 40px);
  line-height: 1;
  font-weight: 900;
  color: #ffffff;
  text-transform: uppercase;
}

.gaming-core-entry small {
  max-width: 68ch;
  margin-top: 12px;
  color: #e5fbff;
  line-height: 1.45;
  font-size: 16px;
  font-weight: 700;
}

@media (prefers-reduced-motion: reduce) {
  .gaming-core-entry {
    transition: none;
  }

  .gaming-core-entry:hover,
  .gaming-core-entry:focus-visible {
    transform: none;
  }
}

.portal-gaming-entry {
  margin: 0 0 18px;
}

.login-form {
  display: grid;
  gap: 14px;
}

.login-form label {
  display: grid;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
}

.login-form input,
.search-shell input {
  border: 0;
  outline: 0;
}

.login-form input {
  min-height: 46px;
  border-radius: 999px;
  border: 1px solid var(--surface-border);
  padding: 0 16px;
  background: #f8fbff;
}

.solid-button,
.ghost-button,
.request-button {
  border: 0;
  border-radius: 10px;
  min-height: 48px;
  padding: 0 16px;
  font-weight: 600;
  cursor: pointer;
  transition: 0.18s ease;
}

.solid-button:disabled,
.ghost-button:disabled,
.request-button:disabled,
.icon-button:disabled {
  cursor: wait;
  opacity: 0.64;
}

.button-loading {
  position: relative;
  pointer-events: none;
}

.button-loading::before {
  content: "";
  width: 14px;
  height: 14px;
  margin-right: 8px;
  display: inline-block;
  vertical-align: -2px;
  border-radius: 999px;
  border: 2px solid currentColor;
  border-right-color: transparent;
  animation: spin 720ms linear infinite;
}

.solid-button {
  background: var(--secondary);
  color: #fff;
}

.solid-button:hover,
.request-button:hover {
  opacity: 0.92;
}

.ghost-button {
  background: #fff;
  color: var(--text);
  border: 1px solid var(--surface-border);
}

.ghost-button:hover,
.nav-item:hover,
.icon-button:hover {
  background: var(--surface-soft);
}

.danger-button {
  color: var(--danger);
  border-color: rgba(198, 40, 40, 0.28);
}

.danger-button:hover {
  background: rgba(198, 40, 40, 0.08);
}

.error-line {
  margin: 14px 0 0;
  color: var(--danger);
  font-size: 14px;
  font-weight: 600;
}

.error-line[data-kind="info"],
.validator-inline-message[data-kind="info"] {
  color: #075985;
}

.error-line[data-kind="success"],
.validator-inline-message[data-kind="success"] {
  color: var(--secondary);
}

.error-line[data-kind="error"],
.validator-inline-message[data-kind="error"] {
  color: var(--danger);
}

.app-shell {
  display: flex;
  min-height: 100vh;
}

.sidebar {
  position: fixed;
  inset: 0 auto 0 0;
  width: var(--sidebar-width);
  background: var(--surface);
  border-right: 1px solid var(--surface-border);
  padding: 22px 16px;
  display: flex;
  flex-direction: column;
  z-index: 30;
  max-width: 100vw;
  min-width: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.menu-toggle-button {
  display: inline-grid;
  flex: none;
}

.sidebar-nav {
  margin-top: 22px;
  display: grid;
  gap: 4px;
  padding-bottom: 22px;
  min-width: 0;
}

.nav-item {
  width: 100%;
  min-width: 0;
  min-height: 42px;
  border: 0;
  background: transparent;
  color: var(--text-muted);
  border-radius: 10px;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 8px 10px;
  cursor: pointer;
  text-align: left;
  position: relative;
  line-height: 1.2;
  height: auto;
  overflow: visible;
}

.nav-item span:last-child {
  flex: 1 1 auto;
  min-width: 0;
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  overflow-wrap: anywhere;
}

.nav-item .material-symbols-outlined {
  flex: 0 0 auto;
  margin-top: -1px;
}

.nav-item.active {
  color: var(--secondary);
  background: rgba(234, 237, 255, 0.78);
  font-weight: 700;
  box-shadow: inset -2px 0 0 var(--secondary);
}

.nav-group-label {
  display: block;
  margin: 14px 10px 6px;
  color: var(--text-soft);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.request-button {
  margin-top: auto;
  background: var(--primary);
  color: #fff;
}

.app-main {
  margin-left: var(--sidebar-width);
  width: calc(100% - var(--sidebar-width));
  min-width: 0;
  transition: margin-left 0.2s ease, width 0.2s ease;
}

.app-shell.sidebar-collapsed .sidebar {
  width: 82px;
  padding-inline: 14px;
}

.app-shell.sidebar-collapsed .sidebar-brand div,
.app-shell.sidebar-collapsed .nav-item span:last-child,
.app-shell.sidebar-collapsed .nav-group-label,
.app-shell.sidebar-collapsed .request-button {
  display: none;
}

.app-shell.sidebar-collapsed .nav-item {
  justify-content: center;
  padding: 0;
}

.app-shell.sidebar-collapsed .app-main {
  margin-left: 82px;
  width: calc(100% - 82px);
}

.app-shell.sidebar-collapsed .topbar {
  left: 82px;
}

.rms-machine-head {
  align-items: flex-start;
}

.view-head-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.rms-machine-hero {
  display: grid;
  grid-template-columns: minmax(280px, 1.1fr) minmax(320px, 1.4fr);
  gap: 16px;
  align-items: stretch;
  margin-bottom: 18px;
}

.rms-machine-principle,
.rms-workday-shell {
  background: var(--surface);
  border: 1px solid var(--surface-border);
  border-radius: 8px;
  padding: 18px;
}

.rms-machine-principle h3 {
  margin: 8px 0;
  font-size: 22px;
  line-height: 1.2;
}

.rms-machine-principle p {
  margin: 0;
  color: var(--text-muted);
}

.rms-machine-kpis {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.rms-kpi-card {
  background: var(--surface);
  border: 1px solid var(--surface-border);
  border-radius: 8px;
  padding: 16px;
  display: grid;
  gap: 6px;
  min-height: 118px;
}

.rms-kpi-card strong {
  font-size: 24px;
  color: var(--text);
}

.rms-kpi-card small {
  color: var(--text-muted);
}

.rms-workday-shell {
  margin-bottom: 18px;
}

.rms-daily-queue {
  display: grid;
  grid-template-columns: repeat(5, minmax(260px, 1fr));
  gap: 14px;
  align-items: start;
  overflow-x: auto;
  padding-bottom: 6px;
}

.rms-queue-section {
  min-width: 260px;
  background: var(--surface-soft);
  border: 1px solid var(--surface-border);
  border-radius: 8px;
  padding: 12px;
}

.rms-queue-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 12px;
}

.rms-queue-head h3 {
  margin: 3px 0 0;
  font-size: 15px;
}

.rms-queue-head strong {
  min-width: 34px;
  height: 28px;
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
  color: #fff;
  background: var(--secondary);
  font-size: 13px;
}

.rms-card-stack {
  display: grid;
  gap: 10px;
}

.rms-opportunity-card,
.rms-loading-card {
  background: var(--surface);
  border: 1px solid var(--surface-border);
  border-radius: 8px;
  padding: 12px;
}

.rms-loading-card {
  display: flex;
  gap: 12px;
  align-items: center;
  grid-column: 1 / -1;
}

.rms-loading-card p {
  margin: 4px 0 0;
  color: var(--text-muted);
}

.rms-card-topline,
.rms-card-title,
.rms-card-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.rms-card-title {
  align-items: flex-start;
  margin-top: 10px;
}

.rms-card-title strong {
  font-size: 16px;
}

.rms-card-title small {
  color: var(--text-muted);
  text-align: right;
}

.rms-priority,
.rms-risk {
  border-radius: 999px;
  padding: 5px 8px;
  font-size: 11px;
  font-weight: 800;
}

.rms-priority.critical {
  background: rgba(198, 40, 40, 0.12);
  color: #9f1239;
}

.rms-priority.high {
  background: rgba(245, 158, 11, 0.16);
  color: #92400e;
}

.rms-priority.medium {
  background: rgba(7, 89, 133, 0.12);
  color: #075985;
}

.rms-priority.low {
  background: rgba(100, 116, 139, 0.13);
  color: #475569;
}

.rms-priority.premium {
  background: rgba(181, 121, 17, 0.18);
  color: #7c4a03;
}

.rms-risk {
  background: rgba(15, 23, 42, 0.06);
  color: var(--text-muted);
}

.rms-card-facts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin: 12px 0;
}

.rms-card-facts div {
  min-width: 0;
  background: var(--surface-soft);
  border-radius: 6px;
  padding: 8px;
}

.rms-card-facts dt {
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
}

.rms-card-facts dd {
  margin: 3px 0 0;
  font-weight: 700;
  overflow-wrap: anywhere;
}

.rms-card-reason {
  border-left: 3px solid var(--secondary);
  padding-left: 10px;
  margin: 12px 0;
}

.rms-card-reason p,
.rms-next-action p {
  margin: 4px 0 0;
  color: var(--text-muted);
  font-size: 13px;
  line-height: 1.45;
}

.rms-next-action {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  background: rgba(234, 237, 255, 0.48);
  border-radius: 8px;
  padding: 10px;
  margin-bottom: 12px;
}

.rms-next-action .material-symbols-outlined {
  color: var(--secondary);
}

.rms-card-actions {
  justify-content: flex-start;
  flex-wrap: wrap;
}

.rms-journey-shell,
.rms-playbook-shell {
  margin-bottom: 18px;
}

.rms-stage-board {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(210px, 1fr);
  gap: 12px;
  overflow-x: auto;
  padding-bottom: 4px;
}

.rms-stage-column {
  min-width: 210px;
  background: var(--surface-soft);
  border: 1px solid var(--surface-border);
  border-radius: 8px;
  padding: 10px;
}

.rms-stage-head {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  align-items: center;
  margin-bottom: 10px;
}

.rms-stage-head span {
  color: var(--text-muted);
  font-weight: 700;
}

.rms-stage-items {
  display: grid;
  gap: 8px;
}

.rms-stage-item {
  border: 1px solid var(--surface-border);
  background: var(--surface);
  border-radius: 7px;
  padding: 10px;
  text-align: left;
  cursor: pointer;
}

.rms-stage-item strong,
.rms-stage-item small {
  display: block;
}

.rms-stage-item small,
.rms-stage-empty {
  color: var(--text-muted);
}

.rms-stage-empty {
  font-size: 13px;
}

.rms-rule-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.rms-rule-grid article {
  background: var(--surface-soft);
  border: 1px solid var(--surface-border);
  border-radius: 8px;
  padding: 14px;
}

.rms-rule-grid p {
  margin: 6px 0 0;
  color: var(--text-muted);
}

@media (max-width: 980px) {
  .rms-machine-hero {
    grid-template-columns: 1fr;
  }

  .rms-daily-queue {
    grid-template-columns: repeat(5, minmax(250px, 78vw));
  }

  .rms-rule-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 680px) {
  .rms-machine-head,
  .rms-card-title {
    display: grid;
  }

  .view-head-actions {
    justify-content: flex-start;
  }

  .rms-machine-kpis,
  .rms-card-facts,
  .rms-rule-grid {
    grid-template-columns: 1fr;
  }

  .rms-daily-queue {
    grid-template-columns: repeat(5, minmax(238px, 86vw));
  }
}

.rms-flow-chip {
  display: inline-flex;
  width: fit-content;
  margin-top: 8px;
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(39, 71, 132, 0.1);
  color: var(--secondary);
  font-size: 12px;
  font-weight: 800;
}

.rms-empty-guide,
.missions-hero,
.missions-dashboard-grid {
  margin-bottom: 18px;
}

.rms-empty-guide {
  display: grid;
  gap: 14px;
  background: var(--surface);
  border: 1px solid var(--surface-border);
  border-radius: 8px;
  padding: 18px;
}

.rms-empty-head,
.missions-hero {
  display: grid;
  grid-template-columns: minmax(280px, 1.1fr) minmax(320px, 1.4fr);
  gap: 16px;
  align-items: stretch;
}

.rms-empty-head {
  align-items: start;
}

.rms-empty-head p,
.missions-onboarding p {
  margin: 6px 0 0;
  color: var(--text-muted);
  line-height: 1.5;
}

.rms-empty-paths,
.mission-template-grid,
.missions-kpis {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.missions-kpis {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.rms-empty-paths article,
.missions-onboarding,
.mission-template-card,
.mission-active-card,
.mission-reward-card,
.rms-empty-queue-card,
.rms-collector-active-card,
.rms-stage-empty-block {
  background: var(--surface-soft);
  border: 1px solid var(--surface-border);
  border-radius: 8px;
}

.rms-empty-paths article,
.missions-onboarding,
.mission-template-card,
.mission-active-card {
  padding: 14px;
}

.rms-empty-paths .material-symbols-outlined {
  color: var(--secondary);
  font-size: 28px;
}

.rms-empty-paths h4,
.mission-template-card h4,
.mission-active-card h4 {
  margin: 8px 0 6px;
}

.rms-empty-paths p,
.mission-template-card p,
.mission-active-card p,
.rms-stage-empty-block small {
  color: var(--text-muted);
  line-height: 1.45;
}

.button-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  align-items: center;
}

.rms-start-steps {
  background: var(--surface-soft);
  border: 1px solid var(--surface-border);
  border-radius: 8px;
  padding: 14px;
}

.rms-start-steps ol {
  display: grid;
  gap: 8px;
  padding: 0;
  margin: 12px 0 0;
  list-style: none;
}

.rms-start-steps li {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  background: var(--surface);
  border: 1px solid var(--surface-border);
  border-radius: 8px;
  padding: 10px;
}

.rms-start-steps li span,
.rms-how-steps span,
.mission-rank-row span {
  display: inline-grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 999px;
  color: #fff;
  background: var(--secondary);
  font-size: 12px;
  font-weight: 900;
}

.rms-start-steps li button,
.rms-stage-empty-block button {
  border: 0;
  border-radius: 6px;
  background: rgba(39, 71, 132, 0.1);
  color: var(--secondary);
  font-weight: 800;
  padding: 8px 10px;
  cursor: pointer;
}

.rms-rule-action {
  margin-top: 14px;
}

.rms-empty-queue-card {
  grid-column: 1 / -1;
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: center;
  padding: 16px;
}

.rms-empty-queue-card h3,
.rms-empty-queue-card p {
  margin: 0;
}

.rms-empty-queue-card p {
  margin-top: 6px;
  color: var(--text-muted);
}

.rms-collector-active-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(240px, 0.6fr) auto;
  gap: 14px;
  align-items: center;
  padding: 14px;
  border-color: rgba(5, 42, 107, 0.28);
}

.rms-collector-active-card h4,
.rms-collector-active-card p,
.rms-collector-active-card dl {
  margin: 0;
}

.rms-collector-active-card p {
  margin-top: 6px;
  color: var(--text-muted);
  line-height: 1.45;
}

.rms-collector-active-card dl {
  display: grid;
  gap: 8px;
}

.rms-collector-active-card dt {
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}

.rms-collector-active-card dd {
  margin: 2px 0 0;
  font-weight: 800;
}

.rms-stage-empty-block {
  display: grid;
  gap: 7px;
  padding: 10px;
}

.missions-head {
  align-items: flex-start;
}

.missions-onboarding h3 {
  margin: 8px 0;
  font-size: 24px;
  line-height: 1.18;
}

.missions-dashboard-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(300px, 0.65fr);
  gap: 16px;
}

.missions-dashboard-grid .span-2 {
  grid-column: span 1;
}

.missions-panel {
  min-width: 0;
}

.mission-template-card {
  display: grid;
  gap: 10px;
}

.mission-type {
  width: fit-content;
  padding: 5px 8px;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.06);
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 900;
}

.mission-template-meta,
.mission-active-card dl {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.mission-template-meta span,
.mission-active-card dl div {
  background: var(--surface);
  border: 1px solid var(--surface-border);
  border-radius: 7px;
  padding: 8px;
  color: var(--text-muted);
  font-size: 12px;
}

.mission-active-list,
.mission-reward-list,
.mission-leaderboard {
  display: grid;
  gap: 10px;
}

.mission-active-card {
  display: grid;
  gap: 12px;
}

.mission-active-card dl {
  margin: 0;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.mission-active-card dt {
  color: var(--text-muted);
  font-size: 11px;
  text-transform: uppercase;
  font-weight: 800;
}

.mission-active-card dd {
  margin: 4px 0 0;
  font-weight: 900;
}

.mission-rank-row,
.mission-reward-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 10px;
}

.mission-reward-card {
  grid-template-columns: minmax(0, 1fr) auto;
}

.mission-rank-row strong,
.mission-reward-card strong,
.mission-reward-card small {
  overflow-wrap: anywhere;
}

.mission-rank-row small,
.mission-reward-card small {
  color: var(--text-muted);
}

.rms-collector-summary {
  background: var(--surface-soft);
  border: 1px solid var(--surface-border);
  border-radius: 8px;
  padding: 12px;
}

.rms-how-steps {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.rms-how-steps article {
  background: var(--surface-soft);
  border: 1px solid var(--surface-border);
  border-radius: 8px;
  padding: 14px;
}

.rms-how-steps strong,
.rms-how-steps p {
  display: block;
  margin-top: 8px;
}

.rms-how-steps p {
  color: var(--text-muted);
}

.mission-wizard-card,
.rms-collector-card,
.rms-how-card {
  max-width: min(980px, calc(100vw - 28px));
}

.mission-wizard-form,
.rms-collector-form {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.checkbox-line {
  display: flex;
  gap: 10px;
  align-items: center;
}

.checkbox-line input {
  width: auto;
}

@media (max-width: 980px) {
  .rms-empty-head,
  .missions-hero,
  .missions-dashboard-grid,
  .revenue-workspace-head,
  .revenue-main-grid,
  .revenue-action-form,
  .mission-wizard-form,
  .rms-collector-form {
    grid-template-columns: 1fr;
  }

  .rms-empty-paths,
  .mission-template-grid,
  .missions-kpis {
    grid-template-columns: 1fr;
  }

  .rms-start-steps li,
  .rms-empty-queue-card,
  .rms-collector-active-card,
  .mission-active-card dl,
  .revenue-onboarding,
  .rms-how-steps {
    grid-template-columns: 1fr;
  }
}

.topbar {
  position: fixed;
  top: 0;
  right: 0;
  left: var(--sidebar-width);
  height: var(--topbar-height);
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--surface-border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 0 24px;
  z-index: 20;
  min-width: 0;
}

.search-shell {
  flex: 1 1 320px;
  width: min(560px, 52vw);
  min-width: 220px;
  max-width: 560px;
  min-height: 42px;
  border-radius: 999px;
  background: var(--surface-soft);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 16px;
  color: var(--text-soft);
}

.search-shell input {
  width: 100%;
  background: transparent;
}

.topbar-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  flex: 0 1 auto;
  justify-content: flex-end;
}

.revenue-global-button {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  white-space: nowrap;
}

.icon-button {
  width: 40px;
  height: 40px;
  border-radius: 999px;
  border: 0;
  background: transparent;
  color: var(--text-muted);
  display: grid;
  place-items: center;
  cursor: pointer;
}

.profile-block {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-left: 16px;
  border-left: 1px solid var(--surface-border);
  min-width: 0;
}

.profile-block span:last-child {
  max-width: 150px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.profile-avatar {
  width: 34px;
  height: 34px;
  border-radius: 999px;
  background: linear-gradient(135deg, #00bfe5, #063a9f);
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 12px;
  font-weight: 700;
}

.content-shell {
  padding: calc(var(--topbar-height) + 28px) 28px 28px;
  max-width: 100%;
  min-width: 0;
  overflow-x: hidden;
}

.subscription-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 18px;
  padding: 18px 20px;
  border: 1px solid rgba(37, 99, 235, 0.18);
  border-radius: 18px;
  background:
    linear-gradient(135deg, rgba(37, 99, 235, 0.08), rgba(0, 191, 229, 0.07)),
    var(--surface);
  box-shadow: 0 18px 42px rgba(15, 23, 42, 0.08);
}

.subscription-banner h3 {
  margin: 4px 0 6px;
  font-size: 18px;
}

.subscription-banner p {
  margin: 0;
  color: var(--muted);
}

.subscription-banner[data-access-status="GRACE"] {
  border-color: rgba(245, 158, 11, 0.5);
}

.subscription-banner[data-access-status="LOCKED"] {
  border-color: rgba(239, 68, 68, 0.55);
}

.subscription-timing {
  margin-top: 6px !important;
  font-weight: 700;
}

.subscription-limits {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.subscription-limit-chip {
  display: inline-flex;
  min-height: 34px;
  align-items: center;
  padding: 0 12px;
  border-radius: 999px;
  color: var(--text);
  background: rgba(15, 23, 42, 0.06);
  border: 1px solid rgba(15, 23, 42, 0.08);
  font-size: 12px;
  font-weight: 700;
}

.account-summary-grid,
.account-settings-grid {
  display: grid;
  gap: 18px;
  margin-bottom: 18px;
}

.account-summary-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.account-settings-grid {
  grid-template-columns: minmax(0, 1.35fr) minmax(280px, 0.65fr);
  align-items: start;
}

.account-profile-card,
.account-settings-card {
  min-width: 0;
}

.account-profile-card h3,
.account-settings-card h3 {
  margin: 6px 0 14px;
}

.account-meta-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.account-meta-grid div {
  min-width: 0;
  padding: 12px;
  border: 1px solid var(--surface-border);
  border-radius: 10px;
  background: var(--surface-soft);
}

.account-meta-grid span {
  display: block;
  margin-bottom: 5px;
  color: var(--text-soft);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
}

.account-meta-grid strong {
  display: block;
  overflow-wrap: anywhere;
  font-size: 14px;
  color: var(--text);
}

.account-deal-card {
  margin-bottom: 18px;
}

.account-deal-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-top: 14px;
}

.account-deal-grid div {
  min-width: 0;
  padding: 12px;
  border: 1px solid var(--surface-border);
  border-radius: 10px;
  background: var(--surface-soft);
}

.account-deal-grid span {
  display: block;
  margin-bottom: 5px;
  color: var(--text-soft);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
}

.account-deal-grid strong {
  display: block;
  overflow-wrap: anywhere;
  font-size: 14px;
  color: var(--text);
}

.account-profile-form {
  margin-top: 16px;
}

.business-logo-profile-slot {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 18px;
}

.account-billing-card {
  grid-column: 1 / -1;
}

.account-billing-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-top: 14px;
}

.account-billing-panel {
  min-width: 0;
  display: grid;
  gap: 10px;
  align-content: start;
  padding: 14px;
  border: 1px solid var(--surface-border);
  border-radius: 10px;
  background: var(--surface-soft);
}

.account-billing-panel strong,
.account-billing-panel p {
  margin: 0;
}

.account-billing-panel label {
  display: grid;
  gap: 6px;
  color: var(--text-muted);
  font-size: 13px;
  font-weight: 700;
}

.auto-renew-clarity {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  padding: 10px;
  border: 1px solid rgba(229, 251, 255, 0.18);
  border-radius: 8px;
  background: rgba(8, 20, 38, 0.72);
}

.auto-renew-clarity div {
  min-width: 0;
  display: grid;
  gap: 4px;
  padding: 8px;
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.04);
}

.auto-renew-clarity span {
  color: #e5fbff;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0;
  text-transform: uppercase;
}

.auto-renew-clarity strong {
  color: #f8fdff;
  font-size: 12px;
  line-height: 1.2;
}

.auto-renew-clarity small {
  color: #a8c6d9;
  font-size: 11px;
  line-height: 1.35;
}

.business-logo-preview.compact {
  width: 92px;
  height: 92px;
  min-width: 92px;
}

.ticket-frame-preview {
  width: 96px;
  min-width: 96px;
  aspect-ratio: 4 / 5;
  display: grid;
  place-items: center;
  overflow: hidden;
  border: 1px dashed var(--surface-border);
  border-radius: 10px;
  background: var(--surface-soft);
  color: var(--text-muted);
}

.ticket-frame-preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.hidden-file-input {
  display: none;
}

.inline-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}

.nav-item.plan-locked,
.activation-type-option.plan-locked {
  opacity: 0.56;
}

.activation-type-option.feature-tier-applied {
  position: relative;
}

.feature-tier-badge {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  min-height: 18px;
  padding: 2px 6px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.42);
  font-size: 9px;
  line-height: 1;
  font-weight: 900;
  letter-spacing: 0;
  text-transform: uppercase;
  white-space: nowrap;
}

.feature-tier-badge .material-symbols-outlined {
  font-size: 12px;
  line-height: 1;
}

.feature-tier-badge.is-medium {
  color: #006e91;
  background: #e5fbff;
  border-color: #00bfe5;
}

.feature-tier-badge.is-premium {
  color: #5b21b6;
  background: #ede9fe;
  border-color: #c4b5fd;
}

.activation-type-option > .feature-tier-badge {
  position: absolute;
  top: 8px;
  right: 8px;
  margin-left: 0;
}

.action-feedback {
  position: sticky;
  top: calc(var(--topbar-height) + 12px);
  z-index: 25;
  margin-bottom: 20px;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  padding: 14px 16px;
  border-radius: 12px;
  border: 1px solid var(--surface-border);
  background: #f6fbff;
  color: var(--secondary);
  font-size: 14px;
  font-weight: 600;
  box-shadow: 0 16px 32px rgba(19, 27, 46, 0.08);
  animation: feedback-in 180ms ease-out;
}

.action-feedback::before {
  content: "done";
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: rgba(5, 42, 107, 0.12);
  color: var(--secondary);
  font-family: "Material Symbols Outlined";
  font-size: 21px;
  font-weight: 400;
}

.action-feedback p,
.action-feedback strong {
  margin: 0;
}

.action-feedback p {
  margin-top: 2px;
  color: inherit;
  opacity: 0.78;
  font-weight: 500;
}

.action-feedback.error {
  background: #fff2f0;
  color: var(--danger);
  border-color: #f2c4bb;
}

.action-feedback.error::before {
  content: "error";
  background: rgba(198, 40, 40, 0.12);
  color: var(--danger);
}

.action-feedback.loading,
.action-feedback.info {
  background: #eff6ff;
  color: #075985;
  border-color: #bfdbfe;
}

.action-feedback.loading::before {
  content: "";
  border: 3px solid rgba(7, 89, 133, 0.28);
  border-right-color: #075985;
  animation: spin 720ms linear infinite;
}

.action-feedback.info::before {
  content: "info";
  background: rgba(7, 89, 133, 0.12);
  color: #075985;
}

.busy-overlay {
  position: fixed;
  inset: var(--topbar-height) 0 0 var(--sidebar-width);
  z-index: 22;
  display: grid;
  place-items: start center;
  padding-top: 18px;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(249, 248, 246, 0.72), rgba(249, 248, 246, 0));
}

.busy-card {
  width: min(calc(100% - 32px), 520px);
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  padding: 14px 16px;
  border: 1px solid var(--surface-border);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 18px 42px rgba(19, 27, 46, 0.12);
}

.busy-card strong,
.busy-card p {
  margin: 0;
}

.busy-card p {
  margin-top: 3px;
  color: var(--text-muted);
  font-size: 13px;
}

.busy-spinner {
  width: 34px;
  height: 34px;
  border-radius: 999px;
  border: 4px solid rgba(5, 42, 107, 0.16);
  border-right-color: var(--secondary);
  animation: spin 720ms linear infinite;
}

.view-section {
  display: none;
}

.view-section.active {
  display: block;
}

.view-section,
.view-section > *,
.surface-card,
.data-table-card,
.chart-card,
.map-card,
.placeholder-card,
.campaign-rail,
.insight-card,
.explain-card,
.asset-card,
.setting-card,
.metric-card,
.kpi-card {
  min-width: 0;
  max-width: 100%;
}

.view-section h1,
.view-section h2,
.view-section h3,
.view-section h4,
.view-section p,
.view-section strong,
.view-section small,
.view-section span,
.view-section td,
.view-section th,
.modal-card,
.modal-card * {
  overflow-wrap: anywhere;
}

.view-section canvas,
.view-section img,
.modal-card img {
  max-width: 100%;
}

.chart-card {
  overflow: hidden;
}

.solid-button,
.ghost-button,
.danger-button,
.link-button {
  max-width: 100%;
  min-width: 0;
  align-items: center;
  justify-content: center;
}

/* Deja espacio real debajo del header fijo para que ninguna vista quede tapada */
.view-section {
  scroll-margin-top: 96px;
}

.view-section[data-view="affiliates"] {
  padding-top: 0;
  padding-bottom: 8px;
}

.view-section[data-view="affiliates"] .affiliate-layout {
  margin-top: 18px;
}

.view-section[data-view="affiliates"] .view-head {
  margin-bottom: 16px;
  align-items: center;
}

.view-section[data-view="affiliates"] .view-head h2 {
  font-size: clamp(28px, 2.4vw, 36px);
  line-height: 1.05;
  letter-spacing: 0;
}

.view-section[data-view="affiliates"] .view-head p {
  max-width: 760px;
}

.view-section[data-view="affiliates"] table {
  min-width: 1040px;
}

.affiliate-layout {
  display: grid;
  grid-template-columns: minmax(360px, 0.95fr) minmax(420px, 1.05fr);
  gap: 16px;
  align-items: start;
}

.affiliate-panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-height: 100%;
  overflow: hidden;
}

.affiliate-layout > .data-table-card {
  grid-column: 1 / -1;
}

.affiliate-referral-panel {
  grid-column: 1 / -1;
}

.affiliate-referral-panel .affiliate-card-actions {
  grid-template-columns: minmax(140px, 0.35fr) minmax(220px, 1fr) auto;
  align-items: end;
}

.affiliate-finder-panel {
  margin-top: 16px;
}

.affiliate-finder-grid {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) minmax(108px, auto) minmax(148px, auto) minmax(108px, auto);
  gap: 10px;
  align-items: end;
}

.affiliate-finder-grid label {
  display: grid;
  gap: 6px;
}

.affiliate-finder-grid label span {
  color: var(--text-muted);
  font-size: 13px;
  font-weight: 700;
}

.affiliate-finder-grid input {
  width: 100%;
  min-height: 48px;
}

.affiliate-finder-scanner {
  position: relative;
  min-height: 280px;
  margin-top: 12px;
  border: 1px solid rgba(229, 251, 255, 0.24);
  border-radius: 12px;
  overflow: hidden;
  background: #020817;
}

.affiliate-finder-scanner video {
  display: block;
  width: 100%;
  height: 280px;
  object-fit: cover;
}

.affiliate-finder-overlay {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  pointer-events: none;
}

.affiliate-finder-overlay div {
  width: min(70%, 260px);
  aspect-ratio: 1;
  border: 3px solid #e5fbff;
  border-radius: 18px;
  box-shadow: 0 0 0 999px rgba(2, 8, 23, 0.38);
}

.affiliate-finder-results {
  display: grid;
  gap: 8px;
  margin-top: 10px;
}

.affiliate-finder-result {
  display: grid;
  gap: 3px;
  width: 100%;
  padding: 10px 12px;
  border: 1px solid rgba(229, 251, 255, 0.22);
  border-radius: 10px;
  background: rgba(2, 8, 23, 0.46);
  color: #f8fdff;
  text-align: left;
  cursor: pointer;
}

.affiliate-finder-result:hover {
  border-color: rgba(0, 229, 255, 0.55);
  background: rgba(0, 229, 255, 0.1);
}

.affiliate-finder-result span,
.affiliate-finder-result small {
  color: #a8c6d9;
}

.affiliate-selected-summary,
.affiliate-referral-flow {
  border: 1px solid rgba(229, 251, 255, 0.18);
  border-radius: 12px;
  background: linear-gradient(145deg, rgba(5, 15, 31, 0.92), rgba(2, 8, 23, 0.78));
  padding: 14px;
}

.affiliate-selected-empty {
  color: var(--text-muted);
  font-size: 14px;
}

.affiliate-selected-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.affiliate-selected-head strong {
  color: #f8fdff;
  font-size: 18px;
}

.affiliate-selected-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin: 0;
}

.affiliate-selected-grid div {
  min-width: 0;
}

.affiliate-selected-grid dt {
  margin: 0 0 3px;
  color: #e5fbff;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}

.affiliate-selected-grid dd {
  margin: 0;
  color: #f8fdff;
  font-size: 14px;
  font-weight: 800;
  overflow-wrap: anywhere;
}

.affiliate-referral-status {
  color: #f8fdff;
  font-size: 16px;
  font-weight: 800;
  line-height: 1.35;
  margin-bottom: 12px;
}

.affiliate-referral-steps {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.affiliate-referral-steps span {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  border: 1px solid var(--surface-border);
  border-radius: 10px;
  background: rgba(2, 8, 23, 0.62);
  color: #d9edf7;
  font-size: 13px;
  font-weight: 700;
  padding: 9px 10px;
}

.affiliate-referral-steps strong {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 24px;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--secondary);
  color: #fff;
  font-size: 12px;
}

.affiliate-dashboard-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 18px;
}

.affiliate-stat-card {
  min-height: 126px;
  border: 1px solid var(--surface-border);
  border-radius: 12px;
  background:
    linear-gradient(135deg, rgba(5, 42, 107, 0.08), transparent 58%),
    #fff;
  box-shadow: var(--shadow);
  padding: 16px;
  display: grid;
  align-content: space-between;
}

.affiliate-stat-card strong {
  display: block;
  margin-top: 10px;
  color: var(--primary);
  font-size: clamp(24px, 2vw, 34px);
  line-height: 1;
}

.affiliate-stat-card p {
  margin: 10px 0 0;
  color: var(--text-muted);
  font-size: 13px;
  line-height: 1.35;
}

.affiliate-logo-panel {
  margin-bottom: 16px;
}

.affiliate-logo-grid {
  display: grid;
  grid-template-columns: 160px minmax(0, 1fr);
  gap: 16px;
  align-items: center;
}

.business-logo-preview {
  min-height: 120px;
  border: 1px dashed #b8d2e9;
  border-radius: 12px;
  background: #f6fbff;
  display: grid;
  place-items: center;
  overflow: hidden;
  color: var(--text-muted);
}

.business-logo-preview .material-symbols-outlined {
  font-size: 42px;
}

.business-logo-preview img {
  width: 100%;
  height: 120px;
  object-fit: contain;
  padding: 12px;
  display: block;
}

.business-logo-copy {
  display: grid;
  gap: 10px;
}

.business-logo-copy p {
  margin: 0;
  color: var(--text-muted);
  line-height: 1.45;
}

.affiliate-logo-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.affiliate-form {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.affiliate-form .span-2 {
  grid-column: 1 / -1;
}

.affiliate-form label {
  display: grid;
  gap: 6px;
}

.affiliate-form label span {
  color: var(--text-muted);
  font-size: 13px;
  font-weight: 700;
}

.affiliate-card-preview-wrap {
  position: relative;
  min-height: 0;
  aspect-ratio: 1200 / 760;
  border-radius: 12px;
  border: 1px solid rgba(229, 251, 255, 0.22);
  background:
    radial-gradient(circle at 18% 12%, rgba(0, 229, 255, 0.18), transparent 30%),
    radial-gradient(circle at 82% 18%, rgba(255, 45, 247, 0.12), transparent 28%),
    linear-gradient(145deg, rgba(2, 8, 23, 0.94), rgba(3, 13, 28, 0.98));
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 18px;
}

.affiliate-card-preview-wrap img {
  width: min(100%, 760px);
  max-height: none;
  height: auto;
  display: block;
  object-fit: contain;
  image-rendering: auto;
  border-radius: 10px;
  box-shadow: 0 18px 54px rgba(0, 0, 0, 0.34), 0 0 0 1px rgba(229, 251, 255, 0.14);
}

.affiliate-card-preview-wrap.is-empty::before,
.affiliate-card-preview-wrap.is-loading::before {
  content: "Selecciona o crea un afiliado para ver el carnet";
  width: min(100%, 280px);
  padding: 18px;
  border: 1px dashed #d8e6f2;
  border-radius: 12px;
  color: var(--text-muted);
  background: rgba(255, 255, 255, 0.7);
  text-align: center;
  line-height: 1.45;
  font-weight: 700;
}

.affiliate-card-preview-wrap.is-loading::before {
  content: "Generando vista previa...";
}

.affiliate-card-preview-wrap.is-empty img,
.affiliate-card-preview-wrap.is-loading img {
  display: none;
}

.affiliate-panel .table-card-head {
  padding-bottom: 0.25rem;
}

.affiliate-panel .table-card-head strong {
  font-size: 1.15rem;
}

.affiliate-card-note,
.affiliate-card-meta {
  margin: 0;
  color: var(--text-muted);
  font-size: 14px;
  line-height: 1.5;
}

.affiliate-card-actions {
  display: grid;
  grid-template-columns: repeat(3, minmax(140px, 1fr));
  gap: 10px;
  align-items: end;
}

.affiliate-card-actions label {
  display: grid;
  gap: 6px;
}

.affiliate-card-actions label span {
  color: var(--text-muted);
  font-size: 13px;
  font-weight: 700;
}

.affiliate-card-actions .field-group {
  margin: 0;
}

.affiliate-card-actions .span-2 {
  grid-column: span 2;
}

.affiliate-card-actions .span-3 {
  grid-column: 1 / -1;
}

.affiliate-card-actions input[type="number"],
.affiliate-card-actions input[type="text"],
.affiliate-card-actions input[type="url"],
.affiliate-card-actions select {
  width: 100%;
  min-height: 48px;
}

.affiliate-card-actions .solid-button,
.affiliate-card-actions .ghost-button {
  min-height: 48px;
}

#affiliateTable tr[data-affiliate-row-select] {
  cursor: pointer;
}

#affiliateTable tr[data-affiliate-row-select]:focus-visible {
  outline: 2px solid rgba(229, 251, 255, 0.72);
  outline-offset: -2px;
}

.affiliate-purchase-summary,
.affiliate-purchase-line-total {
  display: grid;
  gap: 4px;
}

.affiliate-purchase-summary {
  min-height: 48px;
  padding: 8px 10px;
  border: 1px solid rgba(229, 251, 255, 0.18);
  border-radius: 8px;
  background: rgba(2, 8, 23, 0.36);
}

.affiliate-purchase-summary span,
.affiliate-purchase-summary small,
.affiliate-purchase-line-total span {
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 700;
}

.affiliate-purchase-builder {
  display: grid;
  gap: 10px;
  padding: 12px;
  border: 1px solid rgba(229, 251, 255, 0.16);
  border-radius: 8px;
  background: rgba(2, 8, 23, 0.24);
}

.affiliate-purchase-items {
  display: grid;
  gap: 8px;
}

.affiliate-purchase-builder-head,
.affiliate-purchase-item {
  display: grid;
  gap: 10px;
  align-items: end;
}

.affiliate-purchase-builder-head {
  grid-template-columns: 1fr auto;
}

.affiliate-purchase-item {
  grid-template-columns: minmax(180px, 1fr) minmax(80px, 0.35fr) minmax(120px, 0.6fr) minmax(110px, 0.45fr) auto;
  padding-top: 10px;
  border-top: 1px solid rgba(229, 251, 255, 0.12);
}

.affiliate-purchase-item select,
.affiliate-purchase-item input {
  width: 100%;
  min-width: 0;
}

.reward-pass-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(320px, 0.7fr);
  gap: 20px;
  align-items: start;
}

.reward-pass-ticket-context {
  margin-bottom: 16px;
  padding: 12px 14px;
  border: 1px solid rgba(232, 193, 112, 0.28);
  border-radius: 8px;
  color: #f0d391;
  background: rgba(232, 193, 112, 0.08);
  font-weight: 700;
}

.reward-pass-card-preview {
  width: 100%;
  aspect-ratio: 5 / 3;
  display: grid;
  place-items: center;
  padding: 18px;
  border-radius: 8px;
  border: 1px solid rgba(232, 193, 112, 0.35);
  background: linear-gradient(135deg, rgba(232, 193, 112, 0.18), transparent 38%), #071017;
}

.reward-pass-card-inner {
  width: 100%;
  height: 100%;
  display: grid;
  align-content: center;
  gap: 10px;
  padding: 22px;
  border: 2px solid #e8c170;
  border-radius: 8px;
}

.reward-pass-card-inner span {
  color: #e8c170;
  font-family: "JetBrains Mono", monospace;
  font-size: 0.84rem;
}

.reward-pass-card-inner strong {
  color: #ffffff;
  font-size: clamp(1.8rem, 4vw, 3.2rem);
}

.reward-pass-card-inner p,
.reward-pass-card-inner small {
  margin: 0;
  color: #d7e2eb;
}

.reward-pass-detail-card {
  margin-top: 20px;
}

.reward-pass-detail-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 18px;
}

.reward-pass-detail-item {
  padding: 14px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.reward-pass-detail-item span {
  display: block;
  color: var(--text-muted);
  font-size: 0.72rem;
  text-transform: uppercase;
}

.reward-pass-detail-item strong {
  display: block;
  margin-top: 6px;
  overflow-wrap: anywhere;
}

.affiliate-panel .stacked-field {
  display: grid;
  gap: 6px;
}

.affiliate-panel .stacked-field span {
  color: var(--text-muted);
  font-size: 13px;
  font-weight: 700;
}

.affiliate-photo-capture {
  position: relative;
  min-height: 320px;
  border-radius: 12px;
  overflow: hidden;
  border: 1px dashed #b8d2e9;
  background:
    linear-gradient(135deg, rgba(5, 42, 107, 0.08), transparent 45%),
    #f6fbff;
}

.affiliate-photo-capture.is-live {
  border-style: solid;
  border-color: rgba(5, 42, 107, 0.34);
  box-shadow: inset 0 0 0 3px rgba(0, 191, 229, 0.16);
}

.affiliate-photo-capture.has-photo {
  border-style: solid;
}

.affiliate-camera-preview,
.affiliate-photo-preview {
  width: 100%;
  height: 320px;
  object-fit: cover;
  display: block;
}

.affiliate-camera-preview[hidden],
.affiliate-photo-preview[hidden],
.affiliate-photo-placeholder[hidden] {
  display: none;
}

.affiliate-photo-placeholder {
  min-height: 300px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 8px;
  padding: 24px;
  text-align: center;
  color: var(--text-muted);
}

.affiliate-photo-placeholder .material-symbols-outlined {
  width: 58px;
  height: 58px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #063a9f;
  color: #fff;
  font-size: 30px;
}

.affiliate-photo-placeholder strong {
  color: var(--primary);
  font-size: 16px;
}

.affiliate-photo-placeholder p {
  max-width: 310px;
  margin: 0;
  line-height: 1.45;
}

.affiliate-photo-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.affiliate-photo-actions .ghost-button {
  min-height: 46px;
}

.affiliate-photo-actions .ghost-button:first-child {
  border-color: rgba(5, 42, 107, 0.32);
  background: #eaf4ff;
  color: #063a9f;
}

.affiliate-photo-actions .ghost-button.is-primary-action {
  border-color: rgba(5, 42, 107, 0.38);
  background: var(--secondary);
  color: #fff;
}

.affiliate-photo-actions .ghost-button:disabled {
  cursor: not-allowed;
  opacity: 0.48;
}

.affiliate-stepper {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  padding: 0;
  background: transparent;
}

.affiliate-step {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  padding: 10px;
  border: 1px solid var(--surface-border);
  border-radius: 10px;
  background: #f6fbff;
  color: var(--text);
}

.affiliate-step.is-active {
  border-color: rgba(5, 42, 107, 0.28);
  background: #eaf4ff;
}

.affiliate-step.is-complete {
  border-color: rgba(5, 42, 107, 0.2);
}

.affiliate-step.is-complete .affiliate-step-number {
  background: var(--secondary);
}

.affiliate-step strong {
  display: block;
  color: var(--primary);
  font-size: 13px;
}

.affiliate-step p {
  margin: 2px 0 0;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.35;
}

.affiliate-step-number {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #063a9f;
  color: #fff;
  font-weight: 700;
  font-size: 12px;
  flex: none;
}

.affiliate-file-input {
  display: none;
}

.affiliate-original-photo-field {
  display: none !important;
}

.section-footnote {
  margin: 0;
  color: var(--text-muted);
  font-size: 13px;
  line-height: 1.5;
}

@media (max-width: 1080px) {
  .affiliate-layout {
    grid-template-columns: 1fr;
  }

  .affiliate-form,
  .affiliate-card-actions,
  .affiliate-finder-grid,
  .reward-pass-layout,
  .reward-pass-detail-grid,
  .affiliate-selected-grid,
  .affiliate-referral-steps,
  .affiliate-stepper,
  .affiliate-photo-actions {
    grid-template-columns: 1fr;
  }
}

.view-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 16px;
  margin-bottom: 22px;
}

.view-head h2 {
  margin: 0 0 8px;
  font-size: clamp(34px, 3.2vw, 48px);
  line-height: 1;
  letter-spacing: -0.04em;
  color: var(--primary);
}

.campaign-head h2 {
  margin-top: 4px;
}

.head-actions {
  display: flex;
  align-items: end;
  gap: 12px;
  flex-wrap: wrap;
}

.compact-field {
  display: grid;
  gap: 4px;
  min-width: 220px;
}

.compact-field span {
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.compact-field select {
  min-height: 40px;
}

.breadcrumb {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-muted);
  font-family: "JetBrains Mono", monospace;
  font-size: 12px;
  text-transform: uppercase;
}

.surface-card,
.dark-hero-card,
.dark-insight-card {
  border-radius: var(--radius);
  border: 1px solid var(--surface-border);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.surface-card {
  padding: 18px;
}

.dark-hero-card,
.dark-insight-card {
  background: linear-gradient(180deg, #052a6b 0%, #052a6b 100%);
  color: #fff;
  border-color: rgba(0, 0, 0, 0.08);
}

.mono-label,
.table-card-head,
th,
.segment-tab,
.pill {
  font-family: "JetBrains Mono", monospace;
  letter-spacing: 0.08em;
}

.mono-label {
  color: var(--text-muted);
  font-size: 12px;
  text-transform: uppercase;
}

.kpi-grid {
  display: grid;
  gap: 18px;
}

.ticket-center-menu {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(142px, 1fr));
  gap: 10px;
  margin: 4px 0 20px;
}

.ticket-data-mode {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0 0 16px;
  padding: 12px 14px;
  border: 1px solid rgba(0, 229, 255, 0.28);
  border-radius: 10px;
  background: rgba(0, 229, 255, 0.08);
  color: var(--text);
}

.ticket-data-mode .material-symbols-outlined {
  color: #e5fbff;
}

.ticket-data-mode strong {
  display: block;
  font-size: 13px;
}

.ticket-data-mode p {
  margin: 2px 0 0;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.4;
}

.ticket-center-tab {
  min-height: 58px;
  border: 1px solid var(--surface-border);
  border-radius: 10px;
  background: var(--surface);
  color: var(--text-muted);
