.ticket-center-tab.active {
  color: #061225;
  border-color: rgba(229, 251, 255, 0.58);
  background: linear-gradient(135deg, #00e5ff, #e5fbff);
  font-weight: 800;
  box-shadow: 0 0 22px rgba(0, 229, 255, 0.28);
}

.ticket-center-tab .material-symbols-outlined {
  font-size: 22px;
}

.ticket-center-tab span:last-child {
  overflow-wrap: anywhere;
  line-height: 1.15;
}

.ticket-center-panel {
  display: none;
}

.ticket-center-panel.active {
  display: block;
}

.ticket-module-kpis {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-bottom: 18px;
}

.ticket-module-card {
  display: grid;
  gap: 16px;
}

.ticket-flow-track {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 12px;
}

.ticket-flow-track article,
.ticket-action-card {
  min-width: 0;
  border: 1px solid var(--surface-border);
  border-radius: 10px;
  background: rgba(3, 11, 27, 0.48);
  padding: 14px;
}

.ticket-flow-track article {
  display: grid;
  gap: 8px;
  align-content: start;
}

.ticket-flow-track span,
.ticket-action-number {
  width: 30px;
  height: 30px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  color: #061225;
  background: #e5fbff;
  font-weight: 900;
}

.ticket-flow-track strong,
.ticket-action-card h3 {
  color: #f8fdff;
}

.ticket-flow-track p,
.ticket-action-card p {
  margin: 0;
  color: var(--text-muted);
  line-height: 1.45;
}

.ticket-flow-track b {
  color: #e5fbff;
  font-size: 24px;
}

.ticket-module-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}

.ticket-action-card {
  display: grid;
  gap: 12px;
  align-content: start;
  min-height: 220px;
}

.ticket-action-card h3 {
  margin: 0;
  font-size: 24px;
  line-height: 1.1;
}

.ticket-action-card > .material-symbols-outlined {
  color: #e5fbff;
  font-size: 30px;
}

.ticket-action-card strong {
  color: #f8fdff;
  font-size: 36px;
  line-height: 1;
}

.ticket-risk-card {
  border-color: rgba(255, 77, 141, 0.36);
}

.next-ticket-card {
  min-height: 260px;
}

.next-ticket-card button {
