.business-kpis {
  grid-template-columns: repeat(5, minmax(0, 1fr));
  margin-bottom: 24px;
}

.campaign-kpis,
.sales-kpis {
  grid-template-columns: repeat(5, minmax(0, 1fr));
  margin-bottom: 24px;
}

.customer-sale-form {
  grid-template-columns: 1fr;
  gap: 16px;
}

.sale-form-block {
  min-width: 0;
  display: grid;
  gap: 14px;
  padding: 16px;
  border: 1px solid rgba(229, 251, 255, 0.14);
  border-radius: 10px;
  background: rgba(2, 10, 22, 0.2);
}

.sale-form-block-head {
  display: flex;
  gap: 12px;
  align-items: center;
  min-width: 0;
}

.sale-form-block-head > .material-symbols-outlined {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  flex: 0 0 40px;
  border-radius: 10px;
  color: #00bfe5;
  background: rgba(0, 191, 229, 0.12);
}

.sale-form-block-head strong {
  display: block;
  color: var(--text);
}

.sale-form-grid {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 12px;
  align-items: start;
}

.customer-sale-form .sale-field {
  min-width: 0;
  grid-column: span 4;
  display: grid;
  gap: 7px;
}

.customer-sale-form .sale-field-total,
.customer-sale-form .sale-field-search {
  grid-column: span 5;
}

.customer-sale-form .sale-field-currency {
  grid-column: span 2;
}

.customer-sale-form .sale-field-existing,
.customer-sale-form .sale-field-campaign {
  grid-column: span 5;
}

.customer-sale-form .sale-field-name {
  grid-column: span 6;
}

.customer-sale-form .sale-field-notes {
  grid-column: 1 / -1;
}

.customer-sale-form input,
.customer-sale-form select,
.customer-sale-form textarea {
  width: 100%;
  min-width: 0;
}

.sale-customer-status {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  min-width: 0;
  padding: 12px;
  border: 1px solid rgba(229, 251, 255, 0.16);
  border-radius: 10px;
  background: rgba(229, 251, 255, 0.055);
  color: var(--text);
}

.sale-customer-status > .material-symbols-outlined {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  color: #e5fbff;
  background: rgba(229, 251, 255, 0.11);
}

.sale-customer-status strong,
.sale-customer-status small {
  display: block;
}

.sale-customer-status small {
  margin-top: 2px;
  color: var(--muted);
  line-height: 1.35;
}

.sale-customer-status.is-success {
  border-color: rgba(0, 191, 229, 0.32);
  background: rgba(0, 191, 229, 0.08);
}

.sale-customer-status.is-warning {
  border-color: rgba(232, 193, 112, 0.34);
  background: rgba(232, 193, 112, 0.08);
}

.sale-customer-status.is-error {
  border-color: rgba(255, 77, 141, 0.34);
  background: rgba(255, 77, 141, 0.08);
}

.sale-form-actions {
  display: grid;
  grid-template-columns: minmax(180px, 240px) minmax(0, 1fr);
  gap: 12px;
  align-items: center;
}

.sale-form-actions .error-line {
  margin: 0;
}

.inventory-layout {
  display: grid;
  grid-template-columns: minmax(280px, 0.9fr) minmax(420px, 1.4fr);
  gap: 18px;
  align-items: start;
}

.channel-analytics-layout {
  display: grid;
  grid-template-columns: minmax(300px, 0.85fr) minmax(420px, 1.45fr);
  gap: 18px;
  align-items: start;
}

.channel-form-card {
  min-width: 0;
}

.channel-effort-layout {
  display: grid;
  grid-template-columns: minmax(320px, 0.95fr) minmax(520px, 1.35fr);
  gap: 18px;
  align-items: start;
  margin: 0 0 18px;
}

.channel-effort-form-card,
.channel-effort-results-card {
  min-width: 0;
}

.channel-effort-form {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.channel-effort-form label,
.channel-effort-form input,
.channel-effort-form select,
.channel-effort-form textarea {
  min-width: 0;
  width: 100%;
}

.channel-effort-form label.span-2,
.channel-effort-form .span-2 {
  grid-column: 1 / -1;
}

.channel-effort-results-card .table-wrap {
  max-height: 560px;
  overflow: auto;
}

.channel-effort-results-card table {
  min-width: 1120px;
}

.channel-command-strip {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(320px, 1.05fr);
  gap: 16px;
  margin: 16px 0 18px;
  align-items: stretch;
}

.channel-command-card,
.channel-detail-card {
  min-width: 0;
}

.channel-command-card h3,
.channel-detail-card h3 {
  margin: 6px 0 8px;
  color: #071832;
  line-height: 1.16;
}

.channel-command-card p,
.channel-detail-card p {
  color: #53677f;
  line-height: 1.45;
}

.channel-quick-create {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
}

.channel-quick-create button {
  border: 1px solid #d8e6f2;
  border-radius: 999px;
  background: #f6fbff;
  color: #31506f;
  font-weight: 800;
  padding: 8px 11px;
  cursor: pointer;
}

.channel-quick-create button:hover {
  background: #ffffff;
  border-color: #b8d2e9;
}

.channel-detail-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.channel-detail-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin: 14px 0;
}

.channel-detail-metrics div {
  min-width: 0;
  padding: 10px;
  border: 1px solid #d8e6f2;
  border-radius: 8px;
  background: #f6fbff;
}

.channel-detail-metrics span {
  display: block;
  color: #53677f;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.channel-detail-metrics strong {
  display: block;
  margin-top: 4px;
  color: #071832;
  overflow-wrap: anywhere;
}

.channel-decision-box {
  padding: 12px;
  border: 1px solid #dec77a;
  border-radius: 8px;
  background: #fffaf0;
}

.channel-decision-box p {
  margin: 4px 0 0;
}

.channel-breakdown-list {
  display: grid;
  gap: 8px;
  margin: 14px 0;
}

.channel-breakdown-list > strong {
  color: #071832;
}

.channel-breakdown-list button {
  width: 100%;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 3px 10px;
  padding: 10px;
  border: 1px solid #d8e6f2;
  border-radius: 8px;
  background: #ffffff;
  text-align: left;
  cursor: pointer;
}

.channel-breakdown-list button span,
.channel-breakdown-list button small {
  overflow-wrap: anywhere;
}

.channel-breakdown-list button small {
  grid-column: 1 / -1;
  color: #53677f;
}

.channel-form {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.channel-form label,
.channel-form input,
.channel-form select,
.channel-form textarea {
  min-width: 0;
  width: 100%;
}

.channel-form label.span-2 {
  grid-column: 1 / -1;
}

.inventory-form {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.inventory-form label.span-2 {
  grid-column: 1 / -1;
}

.inventory-table-card input[type="search"] {
  width: min(360px, 100%);
}

.sales-item-builder {
  display: grid;
  gap: 12px;
  padding: 16px;
  border: 1px solid rgba(0, 191, 229, 0.18);
  border-radius: 10px;
  background: rgba(0, 191, 229, 0.055);
  min-width: 0;
}

.sales-item-builder-head,
.sales-total-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-width: 0;
}

.sales-item-builder-head strong,
.sales-total-row strong {
  display: block;
}

.sales-item-builder-head > div {
  min-width: 0;
}

.sales-item-builder-head .ghost-button {
  flex: 0 0 auto;
}

.sales-item-list {
  display: grid;
  gap: 10px;
  min-width: 0;
}

.sales-item-row {
  display: grid;
  grid-template-columns: minmax(260px, 1.7fr) minmax(96px, 0.42fr) minmax(150px, 0.72fr) minmax(132px, 0.58fr) 44px;
  gap: 12px;
  align-items: end;
  padding: 12px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.18);
  min-width: 0;
}

.sales-item-row label {
  min-width: 0;
}

.sales-item-row input,
.sales-item-row select {
  width: 100%;
  min-width: 0;
}

.open-product-input {
  margin-top: 6px;
}

.sales-item-total {
  display: grid;
  gap: 4px;
  min-height: 46px;
  align-content: center;
  min-width: 0;
}

.sales-item-total span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
}

.sales-item-total strong,
.sales-total-row strong {
  overflow-wrap: anywhere;
}

.sales-item-row .icon-button {
  width: 44px;
  min-width: 44px;
  height: 44px;
  align-self: center;
  justify-self: end;
  padding: 0;
}

.sales-total-row {
  padding-top: 10px;
  border-top: 1px solid rgba(148, 163, 184, 0.18);
}

.affiliate-reward-rule-form {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.affiliate-reward-lists {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-top: 14px;
}

.affiliate-reward-rule-list,
.affiliate-reward-unlock-list {
  display: grid;
  gap: 8px;
  margin-top: 8px;
}

.affiliate-reward-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 10px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.22);
}

.affiliate-reward-row strong,
.affiliate-reward-row span {
  display: block;
}

.affiliate-reward-row span {
  color: var(--muted);
  font-size: 12px;
}

.affiliate-reward-row.is-unlocked {
  border-color: rgba(0, 191, 229, 0.42);
}

.affiliate-reward-row.is-locked {
  opacity: 0.78;
}

.table-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.stock-low {
  color: #f97316;
}

@media (max-width: 1080px) {
  .inventory-layout,
  .channel-command-strip,
  .channel-effort-layout,
  .channel-analytics-layout {
    grid-template-columns: 1fr;
  }

  .sale-form-grid {
    grid-template-columns: repeat(6, minmax(0, 1fr));
  }

  .customer-sale-form .sale-field,
  .customer-sale-form .sale-field-total,
  .customer-sale-form .sale-field-currency,
  .customer-sale-form .sale-field-existing,
  .customer-sale-form .sale-field-campaign,
  .customer-sale-form .sale-field-name {
    grid-column: span 3;
  }

  .customer-sale-form .sale-field-search,
  .customer-sale-form .sale-field-notes {
    grid-column: 1 / -1;
  }

  .sales-item-row {
    grid-template-columns: minmax(180px, 1fr) 92px minmax(132px, 0.7fr) 44px;
  }

  .sales-item-total {
    grid-column: 1 / -2;
    grid-template-columns: auto minmax(0, 1fr);
    align-items: center;
    min-height: 28px;
  }

  .sales-item-total strong {
    text-align: right;
  }

  .affiliate-reward-lists {
    grid-template-columns: 1fr;
  }
}

.explain-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
  margin-bottom: 24px;
}

.explain-card {
  display: grid;
  gap: 10px;
  align-content: start;
  min-height: 152px;
}

.explain-card h3 {
  margin: 0;
  font-size: 24px;
  line-height: 1.2;
  color: var(--primary);
}

.explain-card p {
  margin: 0;
  color: var(--text-muted);
  line-height: 1.6;
}

.kpi-card {
  padding: 18px;
  border-radius: var(--radius);
  border: 1px solid #eaf4ff;
  background: #fff;
}

.revenue-workspace {
  display: grid;
  gap: 16px;
  margin-bottom: 20px;
  padding: 18px;
  border: 1px solid rgba(5, 42, 107, 0.22);
  border-radius: 12px;
  background:
    linear-gradient(135deg, rgba(234, 244, 255, 0.62), rgba(255, 255, 255, 0.96)),
    var(--surface);
  box-shadow: var(--shadow);
}

.revenue-workspace-head,
.revenue-main-grid {
  display: grid;
  grid-template-columns: minmax(280px, 1.1fr) minmax(320px, 0.9fr);
  gap: 16px;
  align-items: stretch;
}

.revenue-workspace-head {
  align-items: start;
}

.revenue-workspace-head h3,
.next-best-action-card h3,
.revenue-onboarding h3 {
  margin: 6px 0;
  color: var(--primary);
}

.revenue-workspace-head p,
.next-best-action-card p,
.revenue-onboarding p,
.revenue-path-step p,
.revenue-action-summary p,
.revenue-action-summary small {
  margin: 0;
  color: var(--text-muted);
  line-height: 1.45;
}

.next-best-action-card,
.revenue-objective-card,
.revenue-onboarding,
.revenue-path-step,
.revenue-action-summary {
  border: 1px solid var(--surface-border);
  border-radius: 10px;
  background: var(--surface);
}

.next-best-action-card,
.revenue-objective-card {
  padding: 16px;
}

.next-best-action-card {
  display: grid;
  gap: 10px;
  align-content: start;
}

.next-best-action-card .solid-button,
.revenue-workspace-head .solid-button,
.revenue-onboarding .solid-button {
  width: fit-content;
}

.revenue-objective-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-top: 12px;
}

.revenue-objective-grid button,
.revenue-path-step button {
  border: 1px solid rgba(5, 42, 107, 0.18);
  border-radius: 8px;
  background: rgba(234, 244, 255, 0.48);
  color: var(--secondary);
  font-weight: 800;
  padding: 10px;
  text-align: left;
  cursor: pointer;
}

.revenue-path-guide {
  display: grid;
  grid-template-columns: repeat(7, minmax(145px, 1fr));
  gap: 10px;
  overflow-x: auto;
  padding-bottom: 4px;
}

.revenue-path-step {
  min-width: 145px;
  display: grid;
  gap: 8px;
  padding: 12px;
  align-content: start;
}

.revenue-path-step span {
  display: inline-grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 999px;
  background: rgba(7, 24, 50, 0.16);
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 900;
}

.revenue-path-step.is-active {
  border-color: rgba(5, 42, 107, 0.36);
  background: linear-gradient(180deg, #ffffff, #e5fbff);
}

.revenue-path-step.is-active span {
  background: var(--secondary);
  color: #fff;
}

.revenue-path-step strong {
  color: var(--primary);
}

.revenue-path-step button {
  padding: 8px;
  font-size: 12px;
}

.revenue-onboarding {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) repeat(3, minmax(180px, 0.8fr)) auto;
  gap: 12px;
  align-items: center;
  padding: 14px;
}

.revenue-onboarding article {
  min-height: 86px;
  padding: 10px;
  border-radius: 8px;
  background: var(--surface-soft);
}

.revenue-action-wizard-card {
  max-width: min(960px, calc(100vw - 28px));
}

.revenue-action-form {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.revenue-action-summary {
  display: grid;
  gap: 6px;
  padding: 12px;
  background: var(--surface-soft);
}

.revenue-action-summary h4 {
  margin: 0;
}

@media (max-width: 980px) {
  .revenue-workspace-head,
  .revenue-main-grid,
  .revenue-action-form,
  .revenue-onboarding {
    grid-template-columns: 1fr;
  }

  .revenue-objective-grid {
    grid-template-columns: 1fr;
  }
}

.skeleton-card {
  min-height: 118px;
  overflow: hidden;
  position: relative;
  background: #f6fbff;
  border: 1px solid var(--surface-border);
  border-radius: var(--radius);
}

.skeleton-card::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: translateX(-100%);
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.72), transparent);
  animation: shimmer 1100ms ease-in-out infinite;
}

.kpi-card strong {
  display: block;
  margin: 10px 0 6px;
  font-size: 34px;
  line-height: 1;
  letter-spacing: -0.03em;
}

.kpi-meta {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  color: var(--secondary);
  font-size: 13px;
}

.kpi-meta.negative {
  color: var(--danger);
}

.kpi-card.highlight {
  background: linear-gradient(180deg, #052a6b 0%, #052a6b 100%);
  color: #fff;
}

.kpi-card.highlight .mono-label,
.kpi-card.highlight .kpi-meta {
  color: rgba(255, 255, 255, 0.8);
}

.collapsible-kpi-panel {
  grid-column: 1 / -1;
  min-width: 0;
  border: 1px solid rgba(0, 191, 229, 0.18);
  border-radius: 14px;
  background: rgba(8, 16, 24, 0.72);
  box-shadow: 0 18px 38px rgba(0, 0, 0, 0.16);
  overflow: hidden;
}

.collapsible-kpi-panel summary {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) auto;
  gap: 14px;
  align-items: center;
  min-height: 64px;
  padding: 12px 14px;
  cursor: pointer;
  list-style: none;
}

.collapsible-kpi-panel summary::-webkit-details-marker {
  display: none;
}

.collapsible-kpi-title {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 6px 8px;
  align-items: center;
  min-width: 0;
}

.collapsible-kpi-title .material-symbols-outlined {
  grid-row: span 2;
  color: var(--secondary);
  transition: transform 0.18s ease;
}

.collapsible-kpi-panel[open] .collapsible-kpi-title .material-symbols-outlined {
  transform: rotate(180deg);
}

.collapsible-kpi-title strong {
  min-width: 0;
  color: var(--text);
  font-size: 15px;
  line-height: 1.2;
}

.collapsible-kpi-title small {
  min-width: 0;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.35;
}

.collapsible-kpi-summary {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
  min-width: 0;
}

.collapsible-kpi-summary span {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  min-height: 34px;
  padding: 7px 10px;
  border: 1px solid rgba(0, 191, 229, 0.16);
  border-radius: 999px;
  color: var(--text-muted);
  background: rgba(0, 191, 229, 0.08);
  font-size: 12px;
  white-space: nowrap;
}

.collapsible-kpi-summary b {
  color: var(--text);
  font-size: 15px;
}

.collapsible-kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 180px), 1fr));
  gap: 10px;
  padding: 0 14px 14px;
}

.collapsible-kpi-grid .kpi-card {
  min-height: 124px;
}

.kpi-value.highlight {
  color: var(--primary);
}

.kpi-value.warning {
  color: #b45309;
}

.kpi-value.danger {
  color: var(--danger);
}

.charts-grid {
  display: grid;
  gap: 24px;
}

.dashboard-charts,
.campaign-charts {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-bottom: 24px;
}

.dashboard-deep-grid {
  margin-bottom: 24px;
}

.chart-card canvas {
  width: 100%;
  height: 320px;
  display: block;
  margin-top: 16px;
  cursor: crosshair;
}

.card-head,
.table-card-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
}

.chart-note {
  font-size: 13px;
  color: var(--text-soft);
}

.chart-explainer {
  margin: 8px 0 0;
  max-width: 58ch;
  color: var(--text-muted);
  font-size: 14px;
  line-height: 1.55;
}

.pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 32px;
  padding: 0 12px;
  border-radius: 10px;
  font-size: 12px;
  background: #f1f3f8;
  color: var(--text-muted);
}

.pill.muted {
  background: #fff;
  border: 1px solid var(--surface-border);
}

.tables-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px;
}

.subhead {
  margin: 6px 0 0;
  font-size: 24px;
  line-height: 1.15;
  color: var(--primary);
}

.table-wrap {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  min-width: 640px;
}

th,
td {
  padding: 16px 12px;
  border-bottom: 1px solid #f6fbff;
  text-align: left;
}

th {
  color: var(--text-muted);
  font-size: 12px;
  text-transform: uppercase;
}

td {
  font-size: 15px;
  font-weight: 500;
}

.table-secondary {
