}

.compact-table {
  max-height: 320px;
  overflow: auto;
}

.campaign-affiliate-form {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) minmax(220px, 1fr) auto;
  gap: 12px;
  align-items: end;
}

.campaign-affiliate-form label {
  display: grid;
  gap: 6px;
}

.campaign-affiliate-form select,
.campaign-affiliate-form input {
  width: 100%;
  min-height: 42px;
  border: 1px solid rgba(255, 255, 255, 0.14);
