  font-weight: 600;
  line-height: 1.45;
  text-align: left;
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.28);
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, 6px);
  transition: opacity 0.16s ease, transform 0.16s ease;
  white-space: normal;
}

.field-help::before {
  content: "";
  position: absolute;
  left: 50%;
  bottom: calc(100% + 4px);
  width: 10px;
  height: 10px;
  background: #061225;
  border-right: 1px solid rgba(229, 251, 255, 0.24);
  border-bottom: 1px solid rgba(229, 251, 255, 0.24);
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, 6px) rotate(45deg);
  transition: opacity 0.16s ease, transform 0.16s ease;
}

.field-help:hover::after,
.field-help:focus-visible::after,
.field-help:hover::before,
.field-help:focus-visible::before {
  opacity: 1;
  transform: translate(-50%, 0) rotate(0deg);
}

