/* Neon operations theme */
:root {
  --bg: #020617;
  --surface: rgba(8, 18, 38, 0.9);
  --surface-soft: rgba(14, 31, 65, 0.78);
  --surface-muted: rgba(18, 38, 76, 0.7);
  --surface-border: rgba(74, 222, 255, 0.22);
  --text: #e9fbff;
  --text-muted: #9eb4c8;
  --text-soft: #7187a0;
  --primary: #dffbff;
  --secondary: #00e5ff;
  --secondary-soft: #e5fbff;
  --secondary-pale: rgba(0, 229, 255, 0.16);
  --qori-panel: #061b34;
  --danger: #ff4d8d;
  --shadow: 0 22px 58px rgba(0, 0, 0, 0.42);
  --radius: 10px;
  --neon-cyan: 0 0 22px rgba(0, 229, 255, 0.32);
  --neon-magenta: 0 0 26px rgba(255, 45, 247, 0.24);
}

body {
  background:
    radial-gradient(circle at 10% 8%, rgba(0, 229, 255, 0.22), transparent 26%),
    radial-gradient(circle at 88% 10%, rgba(255, 45, 247, 0.16), transparent 25%),
    linear-gradient(180deg, #020617 0%, #061024 52%, #020617 100%);
  color: var(--text);
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background:
    linear-gradient(rgba(0, 229, 255, 0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 229, 255, 0.06) 1px, transparent 1px);
  background-size: 42px 42px;
  mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0.76), transparent 92%);
}

.portal-shell {
  position: relative;
  z-index: 1;
}

.login-screen {
  background:
    radial-gradient(circle at 20% 18%, rgba(0, 229, 255, 0.24), transparent 28%),
    radial-gradient(circle at 80% 12%, rgba(255, 45, 247, 0.16), transparent 26%),
    linear-gradient(180deg, #020617 0%, #061225 100%);
}

.login-card,
.sidebar,
.topbar,
.subscription-banner,
.surface-card,
.kpi-card,
.dark-hero-card,
.dark-insight-card,
.geo-branch-card,
.modal-card,
.busy-card,
.chart-tooltip {
  background:
    linear-gradient(145deg, rgba(13, 27, 58, 0.94), rgba(3, 7, 18, 0.88));
  border-color: var(--surface-border);
  box-shadow: var(--shadow), var(--neon-cyan);
  backdrop-filter: blur(16px);
}

.login-card {
  border-radius: 16px;
}

.sidebar {
  border-right-color: rgba(0, 229, 255, 0.26);
}

.topbar {
  background: rgba(3, 7, 18, 0.82);
  border-bottom-color: rgba(0, 229, 255, 0.24);
}

.brand-icon,
.profile-avatar {
  background: linear-gradient(135deg, #00e5ff, #ff2df7);
  color: #020617;
  box-shadow: 0 0 22px rgba(0, 229, 255, 0.45);
}

.login-brand h1,
.sidebar-brand h1,
.view-head h2,
.explain-card h3,
.kpi-value.highlight {
  color: #f8fdff;
  text-shadow: 0 0 18px rgba(0, 229, 255, 0.32);
  letter-spacing: 0;
}

.login-brand p,
.sidebar-brand p,
.login-copy p,
.view-head p,
.placeholder-card p,
.map-card p,
.explain-card p,
.chart-explainer,
.chart-note,
.table-secondary,
.geo-branch-card p,
.geo-branch-card span {
  color: var(--text-muted);
}

.login-form input,
.search-shell,
input,
select,
textarea {
  background: rgba(3, 11, 27, 0.82);
  border-color: rgba(74, 222, 255, 0.18);
  color: var(--text);
}

.login-form input:focus,
input:focus,
select:focus,
textarea:focus {
  outline: 0;
  border-color: rgba(0, 229, 255, 0.78);
  box-shadow: 0 0 0 3px rgba(0, 229, 255, 0.12), 0 0 20px rgba(0, 229, 255, 0.22);
}

.solid-button,
.request-button {
  background: linear-gradient(135deg, #00e5ff, #e5fbff);
  color: #001014;
  box-shadow: 0 0 22px rgba(0, 229, 255, 0.34);
}

.ghost-button,
.icon-button,
.nav-item {
  color: var(--text-muted);
}

.ghost-button {
  background: rgba(3, 11, 27, 0.66);
  border-color: rgba(74, 222, 255, 0.22);
}

.ghost-button:hover,
.nav-item:hover,
.icon-button:hover {
  background: rgba(0, 229, 255, 0.09);
  color: #e9fbff;
}

.nav-item.active {
  color: #061225;
  background: linear-gradient(135deg, #00e5ff, #e5fbff);
  box-shadow: 0 0 22px rgba(0, 229, 255, 0.34), inset -2px 0 0 rgba(255, 255, 255, 0.6);
}

.nav-item-core:not(.active) {
  color: #e9fbff;
  background:
    linear-gradient(135deg, rgba(0, 229, 255, 0.12), rgba(0, 191, 229, 0.08)),
    rgba(3, 11, 27, 0.5);
  border: 1px solid rgba(74, 222, 255, 0.2);
  box-shadow: inset 0 0 0 1px rgba(229, 251, 255, 0.04);
}

.nav-item-core:not(.active) .material-symbols-outlined {
  color: #00bfe5;
}

.nav-item.plan-locked {
  opacity: 0.52;
}

.subscription-banner {
  border-color: rgba(248, 232, 90, 0.36);
  background:
    linear-gradient(135deg, rgba(0, 229, 255, 0.12), rgba(255, 45, 247, 0.08)),
    rgba(8, 18, 38, 0.9);
}

.subscription-limit-chip,
.pill,
.status-chip {
  border: 1px solid rgba(74, 222, 255, 0.22);
  background: rgba(0, 229, 255, 0.09);
  color: #dffbff;
}

.status-chip.ok {
  background: rgba(0, 191, 229, 0.16);
  color: #e5fbff;
}

.status-chip.pending {
  background: rgba(248, 232, 90, 0.14);
  color: #fff28a;
}

.status-chip.danger {
  background: rgba(255, 77, 141, 0.16);
  color: #ff8db7;
}

.surface-card,
.kpi-card,
.chart-card,
.data-table-card {
  position: relative;
  overflow: hidden;
}

.surface-card::before,
.kpi-card::before,
.chart-card::before,
.data-table-card::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  background: linear-gradient(120deg, rgba(0, 229, 255, 0.18), transparent 32%, rgba(255, 45, 247, 0.12));
  opacity: 0.52;
}

.surface-card > *,
.kpi-card > *,
.chart-card > *,
.data-table-card > * {
  position: relative;
}

.kpi-card {
  background:
    linear-gradient(145deg, rgba(13, 27, 58, 0.96), rgba(3, 7, 18, 0.9));
  border-color: rgba(74, 222, 255, 0.2);
}

.kpi-card strong {
  color: #f8fdff;
  text-shadow: 0 0 16px rgba(0, 229, 255, 0.28);
}

.kpi-meta {
  color: #e5fbff;
}

.kpi-card.highlight,
.dark-hero-card,
.dark-insight-card {
  background:
    radial-gradient(circle at 20% 10%, rgba(0, 229, 255, 0.24), transparent 34%),
    linear-gradient(145deg, rgba(15, 23, 42, 0.98), rgba(4, 8, 24, 0.96));
  border-color: rgba(248, 232, 90, 0.4);
  box-shadow: var(--shadow), var(--neon-magenta);
}

.chart-card canvas {
  border-radius: 8px;
  background:
    linear-gradient(rgba(0, 229, 255, 0.055) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 229, 255, 0.055) 1px, transparent 1px),
    rgba(2, 6, 23, 0.46);
  background-size: 24px 24px;
  box-shadow: inset 0 0 28px rgba(0, 229, 255, 0.08);
}

table {
  color: var(--text);
}

th {
  color: #e5fbff;
}

td {
  border-color: rgba(74, 222, 255, 0.12);
}

.map-placeholder,
.geo-branch-card {
  background:
    linear-gradient(rgba(3, 7, 18, 0.74), rgba(3, 7, 18, 0.74)),
    repeating-linear-gradient(0deg, rgba(0, 229, 255, 0.08) 0 1px, transparent 1px 24px),
    repeating-linear-gradient(90deg, rgba(0, 229, 255, 0.08) 0 1px, transparent 1px 24px);
}

.map-glow {
  background: rgba(0, 229, 255, 0.9);
  box-shadow: 0 0 26px rgba(0, 229, 255, 0.9), 0 0 44px rgba(255, 45, 247, 0.36);
}

.link-button {
  color: #e5fbff;
}

.error-line[data-kind="info"],
.validator-inline-message[data-kind="info"] {
  color: #e5fbff;
}

.error-line[data-kind="success"],
.validator-inline-message[data-kind="success"] {
  color: #e5fbff;
}

body::after {
  content: "";
  position: fixed;
  top: -18vh;
  right: -12vw;
  width: 64vw;
  height: 132vh;
  pointer-events: none;
  z-index: 0;
  background:
    linear-gradient(104deg, transparent 0 36%, rgba(0, 229, 255, 0.12) 44%, rgba(255, 45, 247, 0.1) 51%, transparent 61%),
    radial-gradient(ellipse at center, rgba(0, 229, 255, 0.16), transparent 56%);
  filter: blur(12px);
  transform: rotate(8deg);
  animation: portal-beam-drift 9s ease-in-out infinite alternate;
}

.topbar,
.sidebar,
.login-card,
.subscription-banner,
.surface-card,
.kpi-card,
.dark-hero-card,
.dark-insight-card,
.geo-branch-card,
.modal-card,
.busy-card,
.chart-tooltip {
  overflow: hidden;
}

.topbar > *,
.sidebar > *,
.login-card > *,
.subscription-banner > *,
.surface-card > *,
.kpi-card > *,
.dark-hero-card > *,
.dark-insight-card > *,
.geo-branch-card > *,
.modal-card > *,
.busy-card > *,
.chart-tooltip > * {
  position: relative;
  z-index: 2;
}

.login-card::after,
.subscription-banner::after,
.surface-card::after,
.kpi-card::after,
.dark-hero-card::after,
.dark-insight-card::after,
.geo-branch-card::after,
.modal-card::after {
  content: "";
  position: absolute;
  inset: -1px;
  pointer-events: none;
  z-index: 1;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(120deg, rgba(0, 229, 255, 0.9), rgba(255, 45, 247, 0.42), rgba(248, 232, 90, 0.58), rgba(0, 229, 255, 0.9));
  background-size: 240% 240%;
  mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  mask-composite: exclude;
  opacity: 0.52;
  animation: portal-border-flow 4.8s linear infinite;
}

.view-section.active .surface-card,
.view-section.active .kpi-card,
.view-section.active .dark-hero-card,
.view-section.active .dark-insight-card,
.subscription-banner {
  animation: portal-levitate 6.2s ease-in-out infinite;
}

.view-section.active .surface-card:nth-child(2n),
.view-section.active .kpi-card:nth-child(2n) {
  animation-delay: -1.7s;
}

.view-section.active .surface-card:nth-child(3n),
.view-section.active .kpi-card:nth-child(3n) {
  animation-delay: -3.2s;
}

.chart-card::before,
.data-table-card::before,
.subscription-banner::before {
  animation: portal-hologram-sweep 6.2s ease-in-out infinite;
}

.chart-card canvas {
  position: relative;
  animation: chart-panel-glow 4.2s ease-in-out infinite;
}

.kpi-card strong,
.dark-hero-card strong,
.dark-insight-card h3,
.subscription-banner h3,
.view-head h2 {
  animation: portal-text-pulse 4s ease-in-out infinite;
}

.solid-button,
.ghost-button,
.request-button,
.icon-button,
.nav-item,
.link-button {
  position: relative;
  overflow: hidden;
}

.solid-button::after,
.ghost-button::after,
.request-button::after,
.icon-button::after,
.nav-item::after,
.link-button::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(110deg, transparent 0 38%, rgba(255, 255, 255, 0.35) 50%, transparent 62%);
  transform: translateX(-135%);
  animation: portal-button-sweep 3.8s ease-in-out infinite;
}

.sidebar::after {
  content: "";
  position: absolute;
  top: 0;
  right: -1px;
  width: 2px;
  height: 100%;
  background: linear-gradient(180deg, transparent, #00e5ff, #ff2df7, #00e5ff, transparent);
  box-shadow: 0 0 22px rgba(0, 229, 255, 0.9);
  animation: sidebar-fiber-flow 5.6s linear infinite;
}

.content-shell::before {
  content: "";
  position: fixed;
  left: var(--sidebar-width);
  right: 0;
  top: var(--topbar-height);
  height: 1px;
  z-index: 3;
  pointer-events: none;
  background: linear-gradient(90deg, transparent, rgba(0, 229, 255, 0.8), rgba(255, 45, 247, 0.58), transparent);
  box-shadow: 0 0 18px rgba(0, 229, 255, 0.55);
  animation: horizontal-fiber-pulse 4.4s ease-in-out infinite;
}

.mono-label::after,
.breadcrumb span:first-child::after {
  content: "";
  display: block;
  width: min(96px, 100%);
  height: 1px;
  margin-top: 6px;
  background: linear-gradient(90deg, rgba(0, 229, 255, 0.9), transparent);
  box-shadow: 0 0 10px rgba(0, 229, 255, 0.7);
}

@keyframes portal-border-flow {
  0% { background-position: 0% 50%; }
  100% { background-position: 240% 50%; }
}

@keyframes portal-levitate {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-5px); }
}

@keyframes portal-hologram-sweep {
  0%, 20% { transform: translateX(-125%); opacity: 0; }
  42% { opacity: 0.52; }
  68%, 100% { transform: translateX(125%); opacity: 0; }
}

@keyframes portal-text-pulse {
  0%, 100% { text-shadow: 0 0 13px rgba(0, 229, 255, 0.24); }
  50% { text-shadow: 0 0 24px rgba(0, 229, 255, 0.55), 0 0 36px rgba(255, 45, 247, 0.22); }
}

@keyframes portal-button-sweep {
  0%, 28% { transform: translateX(-135%); }
  58%, 100% { transform: translateX(135%); }
}

@keyframes portal-beam-drift {
  0% { opacity: 0.36; transform: translateX(0) rotate(8deg); }
  100% { opacity: 0.82; transform: translateX(-9vw) rotate(12deg); }
}

@keyframes chart-panel-glow {
  0%, 100% { box-shadow: inset 0 0 28px rgba(0, 229, 255, 0.08), 0 0 0 rgba(0, 229, 255, 0); }
  50% { box-shadow: inset 0 0 34px rgba(0, 229, 255, 0.16), 0 0 20px rgba(0, 229, 255, 0.16); }
}

@keyframes sidebar-fiber-flow {
  0% { filter: hue-rotate(0deg); opacity: 0.46; }
  50% { filter: hue-rotate(80deg); opacity: 1; }
  100% { filter: hue-rotate(160deg); opacity: 0.46; }
}

@keyframes horizontal-fiber-pulse {
  0%, 100% { opacity: 0.36; transform: scaleX(0.84); }
  50% { opacity: 1; transform: scaleX(1); }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 1ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
  }
}

/* Portal dark comfort mode: stable cards, readable contrast, reduced motion. */
:root {
  --bg: #020617;
  --surface: #071426;
  --surface-soft: #0b1d33;
  --surface-muted: #10243a;
  --surface-border: rgba(229, 251, 255, 0.2);
  --text: #eef7ff;
  --text-muted: #a8c6d9;
  --text-soft: #7f9db1;
  --primary: #e5fbff;
  --secondary: #0759d6;
  --secondary-soft: #e5fbff;
  --secondary-pale: rgba(229, 251, 255, 0.12);
  --qori-panel: #052a6b;
  --shadow: 0 14px 34px rgba(0, 0, 0, 0.24);
  --radius: 10px;
}

body {
  background:
    radial-gradient(circle at 14% 8%, rgba(0, 229, 255, 0.12), transparent 25%),
    radial-gradient(circle at 86% 4%, rgba(255, 45, 247, 0.08), transparent 25%),
    linear-gradient(180deg, #020617 0%, #071225 52%, #020617 100%);
}

body::after,
.content-shell::before,
.sidebar::after {
  display: none;
}

.login-screen {
  background:
    radial-gradient(circle at 12% 10%, rgba(0, 229, 255, 0.12), transparent 28%),
    linear-gradient(180deg, #020617 0%, #071225 100%);
}

.topbar,
.sidebar,
.login-card,
.subscription-banner,
.surface-card,
.kpi-card,
.dark-hero-card,
.dark-insight-card,
.geo-branch-card,
.modal-card,
.busy-card,
.chart-tooltip,
.chart-card,
.data-table-card {
  animation: none !important;
  background:
    linear-gradient(145deg, rgba(9, 22, 48, 0.96), rgba(3, 7, 18, 0.94));
  border-color: var(--surface-border);
  box-shadow: var(--shadow);
  backdrop-filter: none;
  overflow: hidden;
}

.dark-hero-card,
.dark-insight-card,
.subscription-banner {
  background:
    linear-gradient(135deg, rgba(7, 59, 76, 0.96), rgba(9, 31, 52, 0.96));
  color: #f8fbff;
  border-color: rgba(229, 251, 255, 0.18);
}

.login-card::after,
.subscription-banner::after,
.surface-card::after,
.kpi-card::after,
.dark-hero-card::after,
.dark-insight-card::after,
.geo-branch-card::after,
.modal-card::after,
.chart-card::before,
.data-table-card::before,
.subscription-banner::before,
.solid-button::after,
.ghost-button::after,
.request-button::after,
.icon-button::after,
.nav-item::after,
.link-button::after {
  animation: none !important;
  display: none;
}

.chart-card canvas,
.kpi-card strong,
.dark-hero-card strong,
.dark-insight-card h3,
.subscription-banner h3,
.view-head h2 {
  animation: none !important;
  text-shadow: none;
}

.chart-card {
  background:
    radial-gradient(circle at 16% 0%, rgba(0, 229, 255, 0.12), transparent 32%),
    linear-gradient(145deg, rgba(8, 19, 43, 0.98), rgba(2, 6, 23, 0.96)) !important;
  border-color: rgba(229, 251, 255, 0.18) !important;
}

.chart-card canvas {
  border-radius: 10px;
  background: #050f1f;
}

.profile-block {
  padding: 8px 10px;
  border: 1px solid rgba(229, 251, 255, 0.16);
  border-radius: 999px;
  background: rgba(2, 8, 23, 0.58);
}

.solid-button,
.ghost-button,
.request-button,
.icon-button,
.nav-item,
.link-button {
  box-shadow: none;
  transition: background-color 0.16s ease, border-color 0.16s ease, color 0.16s ease, transform 0.16s ease;
}

.solid-button:hover,
.ghost-button:hover,
.request-button:hover,
.icon-button:hover,
.nav-item:hover,
.link-button:hover {
  transform: translateY(-1px);
}

.topbar *,
.sidebar *,
.surface-card *,
.kpi-card *,
.modal-card *,
.chart-card *,
.data-table-card * {
  text-shadow: none !important;
}

.surface-card p,
.kpi-card p,
.view-head p,
.placeholder-card p,
.map-card p,
.profile-detail span,
.setting-card p,
.table-muted,
.muted,
td {
  color: var(--text-muted);
}

.dark-hero-card p,
.dark-insight-card p,
.subscription-banner p {
  color: #dbeafe;
}

input,
select,
textarea {
  background: rgba(2, 8, 23, 0.72);
  color: var(--text);
  border-color: var(--surface-border);
}

@media (max-width: 760px) {
  .account-billing-grid {
    grid-template-columns: 1fr;
  }

  .auto-renew-clarity {
    grid-template-columns: 1fr;
  }

  .topbar,
  .login-card,
  .subscription-banner,
  .surface-card,
  .kpi-card,
  .dark-hero-card,
  .dark-insight-card,
  .geo-branch-card,
  .modal-card,
  .busy-card,
  .chart-card,
  .data-table-card {
    box-shadow: 0 8px 18px rgba(0, 0, 0, 0.24);
  }
}

/* Mobile drawer fix: keep the portal menu fully reachable on phones. */
@media (max-width: 960px) {
  .app-shell.sidebar-open {
    overflow: hidden;
  }

  .sidebar {
    z-index: 42;
    top: 0;
    bottom: 0;
    height: 100vh;
    height: 100dvh;
    max-height: 100dvh;
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
    padding-bottom: max(28px, env(safe-area-inset-bottom));
  }

  .sidebar-brand {
    position: sticky;
    top: 0;
    z-index: 3;
    padding-bottom: 12px;
    background: inherit;
  }

  .sidebar-nav {
    display: grid;
    gap: 8px;
    padding-bottom: 32px;
  }

  .nav-item {
    width: 100%;
    min-height: 46px;
    justify-content: start;
    flex-shrink: 0;
  }

  .app-shell.sidebar-open::after {
    z-index: 32;
  }
}

@media (max-width: 420px) {
  .sidebar {
    width: min(90vw, 336px);
  }

  .sidebar-brand {
    gap: 10px;
  }

  .nav-item {
    min-height: 48px;
    padding-inline: 12px;
  }
}

