/* RMS Data Explorer / Chart Focus Mode */
.chart-focus-root.hidden {
  display: none;
}

body.chart-focus-open {
  overflow: hidden;
}

.chart-focus-overlay {
  position: fixed;
  inset: 0;
  z-index: 1200;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 10px;
  padding: 12px;
  color: #f8fdff;
  background:
    radial-gradient(circle at 14% 12%, rgba(0, 191, 229, 0.18), transparent 28%),
    radial-gradient(circle at 86% 0%, rgba(27, 109, 255, 0.22), transparent 32%),
    rgba(3, 7, 14, 0.96);
  backdrop-filter: blur(18px);
  animation: chartFocusIn 180ms ease-out;
}

.chart-focus-overlay > .active-filters-bar,
.chart-focus-overlay > .data-path-map {
  display: none;
}

.chart-focus-header,
.chart-focus-layout,
.chart-focus-sidebar section,
.chart-focus-stage,
.chart-focus-tab-panel,
.active-filters-bar {
  border: 1px solid rgba(229, 251, 255, 0.2);
  background: linear-gradient(145deg, rgba(6, 16, 30, 0.9), rgba(3, 9, 18, 0.78));
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.chart-focus-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 12px;
  align-items: center;
  padding: 12px 14px;
  border-radius: 14px;
}

.chart-focus-header nav {
  color: #e5fbff;
  font-size: 11px;
  text-transform: uppercase;
}

.chart-focus-header h2 {
  margin: 4px 0;
  font-size: clamp(22px, 2.4vw, 34px);
  letter-spacing: 0;
}

.chart-focus-header p,
.chart-focus-sidebar p,
.chart-focus-sidebar li,
.data-explanation-panel p,
.comparison-panel p {
  color: #c9ddea;
}

.chart-focus-metric {
  min-width: 170px;
  padding: 12px 14px;
  border: 1px solid rgba(0, 191, 229, 0.24);
  border-radius: 14px;
  background: rgba(0, 191, 229, 0.08);
}

.chart-focus-metric span,
.data-explanation-panel span,
.related-metrics-strip span,
.comparison-panel span,
.dictionary-card dt {
  display: block;
  color: #e5fbff;
  font-size: 11px;
  text-transform: uppercase;
}

.chart-focus-metric strong {
  display: block;
  margin-top: 4px;
  color: #ffffff;
  font-size: 24px;
}

.chart-focus-actions,
.chart-focus-tabs,
.focus-chip-row,
.focus-context-actions,
.active-filters-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.chart-focus-actions button,
.chart-focus-tabs button,
.focus-context-actions button,
.active-filters-bar button,
.decision-recommendation-panel button,
.command-focus-button {
  min-height: 38px;
  border: 1px solid rgba(229, 251, 255, 0.24);
  border-radius: 999px;
  color: #f8fdff;
  background: rgba(8, 22, 38, 0.82);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 12px;
  cursor: pointer;
}

.chart-focus-actions button:hover,
.chart-focus-tabs button.active,
.chart-focus-tabs button:hover,
.focus-context-actions button:hover,
.active-filters-bar button:hover,
.decision-recommendation-panel button:hover,
.command-focus-button:hover {
  border-color: rgba(0, 191, 229, 0.62);
  background: linear-gradient(135deg, rgba(0, 191, 229, 0.18), rgba(27, 109, 255, 0.16));
}

.command-focus-button {
  min-height: 32px;
  font-size: 12px;
}

.command-panel-actions {
  position: relative;
  display: inline-flex;
  flex-wrap: nowrap;
  gap: 8px;
  align-items: center;
  justify-content: flex-end;
}

.command-chart-help-button {
  position: relative;
  width: 34px;
  height: 34px;
  border: 1px solid rgba(229, 251, 255, 0.28);
  border-radius: 999px;
  color: #e5fbff;
  background: rgba(229, 251, 255, 0.08);
  display: inline-grid;
  place-items: center;
  cursor: help;
  transition: transform 150ms var(--ease-out-premium, ease), border-color 150ms ease, background 150ms ease, box-shadow 150ms ease;
}

.command-chart-help-button .material-symbols-outlined {
  font-size: 20px;
}

.command-chart-help-button:hover,
.command-chart-help-button:focus-visible {
  border-color: rgba(0, 191, 229, 0.7);
  color: #041018;
  background: #e5fbff;
  box-shadow: 0 0 0 3px rgba(229, 251, 255, 0.12), 0 12px 34px rgba(0, 191, 229, 0.16);
  outline: 0;
  transform: translateY(-1px);
}

.command-help-popover {
  position: absolute;
  right: 0;
  top: calc(100% + 10px);
  z-index: 20;
  width: min(310px, 76vw);
  padding: 13px;
  border: 1px solid rgba(229, 251, 255, 0.26);
  border-radius: 14px;
  color: #eaf7ff;
  background:
    radial-gradient(circle at 12% 10%, rgba(0, 191, 229, 0.14), transparent 38%),
    linear-gradient(145deg, rgba(5, 16, 30, 0.98), rgba(2, 8, 18, 0.96));
  box-shadow: 0 22px 70px rgba(0, 0, 0, 0.42);
  opacity: 0;
  pointer-events: none;
  text-align: left;
  transform: translateY(-4px) scale(0.98);
  transition: opacity 150ms ease, transform 150ms var(--ease-out-premium, ease);
}

.command-help-popover::before {
  content: "";
  position: absolute;
  right: 14px;
  top: -6px;
  width: 10px;
  height: 10px;
  border-left: 1px solid rgba(229, 251, 255, 0.26);
  border-top: 1px solid rgba(229, 251, 255, 0.26);
  background: rgba(5, 16, 30, 0.98);
  transform: rotate(45deg);
}

.command-chart-help-button:hover .command-help-popover,
.command-chart-help-button:focus-visible .command-help-popover {
  opacity: 1;
  transform: translateY(0) scale(1);
}

.command-help-popover strong,
.command-help-popover em,
.command-help-popover small {
  display: block;
}

.command-help-popover strong {
  margin-bottom: 8px;
  color: #ffffff;
