  grid-template-columns: minmax(0, 1fr);
  gap: 14px;
  min-width: 0;
  width: 100%;
  padding: 16px;
  border: 1px solid #eaf4ff;
  border-radius: 12px;
  background: #ffffff;
  transition: border-color 0.18s ease, box-shadow 0.18s ease;
}

.trivia-question-editor.is-complete {
  border-color: #052a6b;
  box-shadow: 0 14px 34px rgba(5, 42, 107, 0.1);
}

.trivia-question-editor > label {
  min-width: 0;
  width: 100%;
}

.trivia-question-editor :where(input, select) {
  width: 100%;
  min-width: 0;
}

.trivia-question-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.trivia-question-head > strong {
  color: #052a6b;
}

.trivia-question-head > span {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  min-height: 26px;
  border-radius: 999px;
  padding: 4px 10px;
  color: #5a4233;
  background: #fff4df;
  font-size: 12px;
  font-weight: 800;
}

.trivia-question-editor.is-complete .trivia-question-head > span {
  color: #052a6b;
  background: #eaf4ff;
}

.trivia-options-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(180px, 1fr));
  gap: 10px;
  min-width: 0;
  width: 100%;
}

.trivia-options-grid label {
  min-width: 0;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  padding: 10px;
  border: 1px solid #eaf4ff;
  border-radius: 10px;
  background: #f6fbff;
}

.trivia-options-grid label > span {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 999px;
  color: #ffffff !important;
  background: #052a6b;
  font-weight: 900;
}

.trivia-options-grid input {
  min-height: 40px;
  padding-inline: 10px;
}

.trivia-launcher-form #triviaLauncherMessage {
  display: none;
  width: 100%;
  margin: 2px 0 0;
  border-radius: 10px;
  padding: 12px 14px;
  border: 1px solid transparent;
  line-height: 1.4;
}

.trivia-launcher-form #triviaLauncherMessage:not(:empty) {
  display: block;
}

.trivia-launcher-form #triviaLauncherMessage[data-kind="info"] {
  color: #075985;
  background: #e8f5ff;
  border-color: #b8dff6;
}

.trivia-launcher-form #triviaLauncherMessage[data-kind="success"] {
  color: #052a6b;
  background: #f6fbff;
  border-color: #e5fbff;
}

.trivia-launcher-form #triviaLauncherMessage[data-kind="error"] {
  color: #8a1f1f;
  background: #fff0f0;
  border-color: #efb5b5;
}

.trivia-launcher-result {
  display: grid;
  gap: 10px;
  margin-top: 16px;
  padding: 16px;
  border: 1px solid #e5fbff;
  border-radius: 10px;
  background: #f6fbff;
}

.trivia-launcher-result strong {
  color: #052a6b;
}

.trivia-launcher-result p {
  margin: 0;
}

.trivia-launcher-result a {
  overflow-wrap: anywhere;
}

.activation-invite-preview {
  display: grid;
  gap: 6px;
}

.activation-invite-preview span {
  color: #052a6b;
  font-size: 0.78rem;
  font-weight: 800;
  text-transform: uppercase;
}

.activation-invite-preview textarea {
  width: 100%;
  min-height: 96px;
  resize: vertical;
  border: 1px solid #e5fbff;
  border-radius: 8px;
  padding: 10px;
  color: #052a6b;
  background: #ffffff;
  font: inherit;
}

#activationShareModal .activation-share-modal-card {
  width: min(96vw, 840px);
}

.activation-share-grid {
  display: grid;
  grid-template-columns: minmax(260px, 0.9fr) minmax(300px, 1.1fr);
  gap: 16px;
  min-height: 0;
}

.activation-share-panel {
  display: grid;
  align-content: start;
  gap: 12px;
  min-width: 0;
}

.activation-share-search {
  display: grid;
  gap: 8px;
}

.activation-share-search > span {
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 800;
  text-transform: uppercase;
}

.activation-share-search div {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
}

.activation-share-search input {
  min-width: 0;
}

.activation-share-lead-list {
  display: grid;
  gap: 8px;
  max-height: min(420px, 50dvh);
  overflow-y: auto;
  padding-right: 4px;
}

.activation-share-lead {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  width: 100%;
  border: 1px solid var(--surface-border);
  border-radius: 8px;
  padding: 10px;
  color: var(--text);
  background: var(--surface-soft);
  text-align: left;
  cursor: pointer;
}

.activation-share-lead.active {
  border-color: #0759d6;
  background: #f6fbff;
}

.activation-share-lead strong,
.activation-share-selected strong {
  display: block;
  color: var(--text);
}

.activation-share-lead small,
.activation-share-selected small {
  display: block;
  margin-top: 4px;
  color: var(--muted);
  overflow-wrap: anywhere;
}

.activation-share-selected {
  border: 1px solid var(--surface-border);
  border-radius: 8px;
  padding: 12px;
  background: var(--surface-soft);
}

.table-card-subtitle {
  margin: 4px 0 0;
  max-width: 640px;
  color: var(--muted);
  font-size: 0.86rem;
  line-height: 1.4;
}

.activation-summary-cell,
.activation-status-cell,
.activation-share-cell {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.activation-title {
  display: block;
  color: var(--text);
  font-size: 0.98rem;
  line-height: 1.24;
}

.activation-meta-line {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.activation-meta-line span {
  border: 1px solid var(--surface-border);
  border-radius: 999px;
  padding: 4px 8px;
  background: var(--surface-soft);
  color: var(--muted);
  font-size: 0.74rem;
  font-weight: 800;
  line-height: 1.1;
}

.activation-summary-cell small,
.activation-status-cell small,
.activation-share-cell small {
  color: var(--muted);
  font-size: 0.78rem;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.activation-metric-stack {
  display: grid;
  min-width: 120px;
  gap: 8px;
}

.activation-metric-stack span {
  display: grid;
  gap: 2px;
  color: var(--muted);
  font-size: 0.74rem;
  font-weight: 800;
  line-height: 1.2;
  text-transform: uppercase;
}

.activation-metric-stack strong {
  color: var(--text);
  font-size: 1rem;
  line-height: 1;
}

.activation-row-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}

.activation-share-actions,
.activation-manage-actions {
  margin-top: 10px;
}

.activation-row-actions .ghost-button {
  min-height: 34px;
  padding: 0 10px;
  border-radius: 8px;
  font-size: 12px;
}

.activation-manage-actions .danger-button {
  border-color: rgba(220, 38, 38, 0.22);
  color: #b42318;
}

.table-link {
  display: inline-block;
  max-width: 240px;
  color: #0759d6;
  font-weight: 800;
  overflow-wrap: anywhere;
  text-decoration: none;
}

.table-link:hover {
  text-decoration: underline;
}

.activation-public-link {
  max-width: 280px;
  border: 1px solid var(--surface-border);
  border-radius: 8px;
  padding: 8px 10px;
  background: var(--surface-soft);
}

.activation-empty-state {
  color: var(--muted);
  font-weight: 700;
  text-align: center;
}

@media (max-width: 720px) {
  .activation-share-grid {
    grid-template-columns: 1fr;
  }

  .activation-share-search div {
    grid-template-columns: 1fr;
  }

  .season-launch-card {
    grid-template-columns: 1fr;
    padding: 20px;
  }

  .season-launch-actions {
    width: 100%;
    min-width: 0;
  }

  .activation-type-picker,
  .benefit-fulfillment-panel .survey-builder-grid,
  .benefit-expiration-panel,
  .ticket-closeout-grid,
  .ticket-closeout-actions,
  .survey-builder-grid,
  .reveal-card-grid {
    grid-template-columns: 1fr;
  }

  .benefit-mode-field,
  .ecommerce-instructions-field,
  .internal-instructions-field {
    grid-column: auto;
    grid-row: auto;
  }

  .activation-type-option {
    min-height: auto;
  }

  .trivia-options-grid {
    grid-template-columns: 1fr;
  }

  .trivia-options-grid label {
    grid-template-columns: 32px minmax(0, 1fr);
  }

  .trivia-question-head {
    align-items: flex-start;
    flex-direction: column;
  }
}

