  border-color: #eaf4ff !important;
}

:root[data-theme="light"] .view-section[data-view="strategic-qr"] .strategic-ticket-operations .danger-button,
:root[data-theme="light"] .view-section[data-view="strategic-qr"] .ticket-status-actions .danger-button {
