/* Lead RMS */
.contact-center-shell {
  display: grid;
  gap: 16px;
}

.lead-export-actions {
  align-items: end;
}

.lead-export-actions .compact-field {
  min-width: min(260px, 100%);
}

.contact-center-operator-panel {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
  padding: 18px;
  border-color: rgba(0, 191, 229, 0.18);
  background:
    linear-gradient(135deg, rgba(0, 191, 229, 0.09), rgba(229, 251, 255, 0.045)),
    rgba(8, 18, 28, 0.58);
}

.contact-center-operator-panel h3 {
  margin: 4px 0 6px;
  color: var(--text);
  font-size: clamp(1.2rem, 1.7vw, 1.75rem);
}

.contact-center-operator-panel p {
  max-width: 820px;
  margin: 0;
  color: var(--muted);
  line-height: 1.45;
}

.contact-center-stage-actions {
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.contact-center-tabs {
  display: flex;
  gap: 8px;
  align-items: stretch;
  margin: 2px 0 16px;
  padding: 8px;
  overflow-x: auto;
  overscroll-behavior-inline: contain;
  border: 1px solid rgba(229, 251, 255, 0.14);
  border-radius: 10px;
  background: rgba(2, 10, 22, 0.34);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.03);
  scrollbar-width: thin;
}

.contact-center-tab-card {
  flex: 1 0 168px;
  min-width: 168px;
  min-height: 58px;
  display: flex;
  gap: 10px;
  align-items: center;
  padding: 9px 10px;
  border: 1px solid transparent;
  border-radius: 8px;
  text-align: left;
  text-transform: none;
  white-space: normal;
  cursor: pointer;
  letter-spacing: 0;
  font-family: "Inter", sans-serif;
  transition: border-color 0.18s ease, background 0.18s ease, color 0.18s ease, transform 0.18s ease;
}

.contact-center-tab-card:hover {
  border-color: rgba(229, 251, 255, 0.24);
  background: rgba(255, 255, 255, 0.06);
}

.contact-center-tab-card:focus-visible {
  outline: 2px solid rgba(229, 251, 255, 0.72);
  outline-offset: 2px;
}

.contact-center-tab-card.active {
  color: #f6fbff;
  border-color: rgba(0, 191, 229, 0.42);
  background: linear-gradient(135deg, rgba(0, 191, 229, 0.18), rgba(229, 251, 255, 0.08));
  box-shadow: inset 0 -2px 0 rgba(0, 191, 229, 0.78), 0 10px 24px rgba(0, 0, 0, 0.12);
}

.contact-tab-copy {
  min-width: 0;
  display: grid;
  gap: 2px;
  overflow: hidden;
}

.contact-center-tab-card strong {
  color: inherit;
  font-size: 0.88rem;
  line-height: 1.15;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.contact-center-tab-card small {
  color: var(--muted);
  font-size: 0.72rem;
  line-height: 1.2;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.contact-center-tab-card em {
  min-width: 30px;
  min-height: 26px;
  margin-left: auto;
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
  padding: 3px 8px;
  color: var(--text);
  background: rgba(255, 255, 255, 0.08);
  font-style: normal;
  font-weight: 800;
  font-size: 0.78rem;
}

.contact-tab-icon {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  color: var(--text);
  background: rgba(0, 191, 229, 0.12);
  font-size: 1.18rem;
}

.contact-center-tab-card.active .contact-tab-icon,
.contact-center-tab-card.active em {
  background: rgba(0, 191, 229, 0.2);
}

.contact-action-feed {
  display: grid;
  gap: 12px;
  margin: 14px 0;
}

.contact-action-feed-head {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
}

.contact-action-feed-head h3 {
  margin: 3px 0;
  color: var(--text);
  font-size: 1.05rem;
}

.contact-action-feed-head p {
  margin: 0;
  color: var(--muted);
  line-height: 1.4;
}

.contact-action-list {
  display: grid;
  gap: 9px;
}

.contact-action-item {
  min-width: 0;
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) minmax(140px, auto);
  gap: 10px;
  align-items: center;
  padding: 11px;
  border: 1px solid rgba(255, 255, 255, 0.11);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.04);
}

.contact-action-item.is-ok {
  border-color: rgba(0, 191, 229, 0.24);
}

.contact-action-item.is-danger {
  border-color: rgba(251, 113, 133, 0.26);
}

.contact-action-item.is-warning {
  border-color: rgba(250, 204, 21, 0.26);
}

.contact-action-item > .material-symbols-outlined {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  color: var(--text);
  background: rgba(0, 191, 229, 0.1);
}

.contact-action-main {
  min-width: 0;
  display: grid;
  gap: 4px;
  border: 0;
  padding: 0;
  color: inherit;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.contact-action-main strong,
.contact-action-main small {
  min-width: 0;
  display: block;
}

.contact-action-main small {
  color: var(--muted);
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.contact-action-main:hover strong {
  color: var(--secondary-soft);
}

.contact-action-side {
  display: grid;
  justify-items: end;
  gap: 5px;
}

.contact-action-side small {
  color: var(--muted);
  font-size: 0.76rem;
}

.contact-action-side .ghost-button {
  min-height: 34px;
  padding: 7px 10px;
}

:root[data-theme="light"] .contact-center-operator-panel {
  border-color: #eaf4ff;
  background: #ffffff;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.06);
}

:root[data-theme="light"] .contact-center-tabs {
  border-color: #eaf4ff;
  background: #f6fbff;
  box-shadow: inset 0 0 0 1px rgba(15, 23, 42, 0.02), 0 8px 18px rgba(15, 23, 42, 0.04);
}

:root[data-theme="light"] .contact-center-tab-card {
  color: #071832;
  background: transparent;
}

:root[data-theme="light"] .contact-center-tab-card:hover {
  border-color: #b8d2e9;
  background: #ffffff;
}

:root[data-theme="light"] .contact-center-tab-card.active {
  border-color: #00bfe5;
  background: #ffffff;
  color: #063a9f;
  box-shadow: inset 0 -2px 0 #0759d6, 0 8px 18px rgba(5, 42, 107, 0.09);
}

:root[data-theme="light"] .contact-tab-icon,
:root[data-theme="light"] .contact-center-tab-card em {
  color: #063a9f;
  background: #f6fbff;
}

@media (max-width: 680px) {
  .contact-center-tabs {
    scroll-snap-type: x proximity;
  }

  .contact-center-tab-card {
    flex-basis: 154px;
    min-width: 154px;
    scroll-snap-align: start;
  }

  .contact-center-tab-card small {
    display: none;
  }
}

:root[data-theme="light"] .contact-action-item {
  border-color: #eaf4ff;
  background: #ffffff;
}

:root[data-theme="light"] .contact-action-item.is-ok {
  border-color: #e5fbff;
  background: #f6fbff;
}

:root[data-theme="light"] .contact-action-item.is-danger {
  border-color: #efaaa9;
  background: #fff7f7;
}

:root[data-theme="light"] .contact-action-item.is-warning {
  border-color: #dfc46b;
  background: #fffbea;
}

:root[data-theme="light"] .contact-action-item > .material-symbols-outlined {
  color: #063a9f;
  background: #f6fbff;
}

:root[data-theme="light"] .contact-center-operator-panel p,
:root[data-theme="light"] .contact-center-tab-card small,
:root[data-theme="light"] .contact-action-feed-head p,
:root[data-theme="light"] .contact-action-main small,
