.contact-center-summary {
  margin: 0;
}

.contact-center-panel {
  display: grid;
  gap: 16px;
}

.contact-center-panel.hidden {
  display: none;
}

#leadAgendaCard {
  min-width: 0;
}

.lead-agenda-toolbar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  margin: 14px 0;
}

.lead-agenda-view-tabs {
  min-width: 0;
  overflow-x: auto;
}

.lead-agenda-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
  align-items: center;
}

.lead-agenda-controls input,
.lead-agenda-controls select {
  min-height: 40px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 8px;
  padding: 8px 10px;
  color: inherit;
  background: rgba(255, 255, 255, 0.055);
}

.lead-agenda-fast-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 10px 0 0;
  padding: 10px;
  border: 1px solid rgba(255, 255, 255, 0.10);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.035);
}

.lead-agenda-create-form,
.lead-agenda-edit-form {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr)) auto;
  gap: 10px;
  align-items: end;
  margin: 12px 0 16px;
  padding: 12px;
  border: 1px solid rgba(0, 191, 229, 0.16);
  border-radius: 8px;
  background: rgba(0, 191, 229, 0.055);
}

.lead-agenda-edit-form {
  width: 100%;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin: 0;
}

.lead-agenda-create-form label,
.lead-agenda-edit-form label {
  min-width: 0;
  display: grid;
  gap: 6px;
}

.lead-agenda-create-form label span,
.lead-agenda-edit-form label span {
  color: var(--muted);
  font-size: 0.78rem;
}

.lead-agenda-create-form input,
.lead-agenda-create-form select,
.lead-agenda-create-form textarea,
.lead-agenda-edit-form input,
.lead-agenda-edit-form select,
.lead-agenda-edit-form textarea {
  width: 100%;
  min-height: 40px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 8px;
  padding: 9px 10px;
  color: inherit;
  background: rgba(255, 255, 255, 0.055);
}

.lead-agenda-create-form textarea,
.lead-agenda-edit-form textarea {
  resize: vertical;
}

.lead-agenda-create-form .span-2,
.lead-agenda-edit-form .span-2 {
  grid-column: span 2;
}

.lead-agenda-edit-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.ghost-button.danger {
  color: #fecaca;
  border-color: rgba(248, 113, 113, 0.34);
}

.lead-agenda-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin: 12px 0 16px;
}

.lead-agenda-board {
  display: grid;
  gap: 14px;
}

.lead-agenda-day {
  min-width: 0;
  display: grid;
  gap: 10px;
}

.lead-agenda-day-head {
  display: flex;
  gap: 10px;
  justify-content: space-between;
  align-items: center;
  padding: 0 2px;
}

.lead-agenda-day-head strong {
  color: var(--text);
}

.lead-agenda-list {
  display: grid;
  gap: 10px;
}

.lead-agenda-item {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(180px, auto);
  gap: 12px;
  align-items: center;
  padding: 13px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.025)),
    rgba(8, 18, 28, 0.62);
}

.lead-agenda-item.is-done {
  opacity: 0.72;
}

.lead-agenda-item.is-editing {
  grid-template-columns: 1fr;
  align-items: stretch;
}

.lead-agenda-meta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
}

.status-chip.priority-low {
  border-color: rgba(148, 163, 184, 0.24);
  background: rgba(148, 163, 184, 0.12);
}

.status-chip.priority-medium {
  border-color: rgba(96, 165, 250, 0.26);
  background: rgba(96, 165, 250, 0.12);
}

.status-chip.priority-high {
  border-color: rgba(250, 204, 21, 0.30);
  background: rgba(250, 204, 21, 0.13);
}

.status-chip.priority-urgent {
  border-color: rgba(248, 113, 113, 0.34);
  background: rgba(248, 113, 113, 0.14);
}

.lead-agenda-progress {
  width: 100%;
  height: 7px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.09);
}

.lead-agenda-progress span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #00bfe5, #facc15);
}

.lead-agenda-checklist {
  display: grid;
  gap: 6px;
}

.lead-agenda-checklist label {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  padding: 7px 8px;
  border: 1px solid rgba(255, 255, 255, 0.10);
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.035);
}

.lead-agenda-checklist input {
  margin-top: 2px;
}

.lead-agenda-checklist input:checked + span {
  color: var(--muted);
  text-decoration: line-through;
}

.lead-agenda-timeline {
  display: grid;
  gap: 8px;
}

.lead-agenda-hour-row {
  display: grid;
  grid-template-columns: 72px minmax(0, 1fr);
  gap: 10px;
  align-items: start;
}

.lead-agenda-hour-row > strong {
  position: sticky;
  left: 0;
  color: var(--muted);
  font-size: 0.82rem;
  line-height: 1.2;
  padding-top: 10px;
}

.lead-agenda-hour-row > div,
.lead-week-column-list,
.lead-agenda-kanban-list {
  display: grid;
  gap: 8px;
}

.lead-agenda-empty-hour {
  display: block;
  min-height: 38px;
  padding: 10px;
  border: 1px dashed rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  color: var(--muted);
}

.lead-agenda-compact-card {
  min-width: 0;
  display: grid;
  gap: 4px;
  border: 1px solid rgba(0, 191, 229, 0.18);
  border-radius: 8px;
  padding: 9px;
  color: inherit;
  text-align: left;
  background: rgba(0, 191, 229, 0.07);
}

.lead-agenda-compact-main {
  display: grid;
  gap: 4px;
  width: 100%;
  border: 0;
  padding: 0;
  color: inherit;
  text-align: left;
  background: transparent;
  cursor: pointer;
}

.lead-agenda-compact-main span,
.lead-agenda-compact-main small {
  color: var(--muted);
}

.lead-agenda-compact-main strong,
.lead-agenda-compact-main small {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.lead-agenda-mini-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  align-items: center;
}

.lead-agenda-mini-actions .ghost-button,
.lead-agenda-mini-actions .solid-button {
  min-height: 28px;
  padding: 5px 7px;
  font-size: 0.74rem;
}

.lead-week-board,
.lead-agenda-kanban {
  display: grid;
  gap: 10px;
  overflow-x: auto;
  padding-bottom: 2px;
}

.lead-week-board {
  grid-template-columns: repeat(7, minmax(168px, 1fr));
}

.lead-week-column,
.lead-agenda-kanban-column {
  min-width: 0;
  display: grid;
  align-content: start;
  gap: 10px;
  padding: 10px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.035);
}

.lead-week-column {
  min-width: 168px;
}

.lead-week-column-head,
.lead-agenda-kanban-head {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  align-items: center;
}

.lead-week-column-head strong {
  text-transform: capitalize;
}

.lead-week-column-head span,
.lead-agenda-kanban-head span {
  color: var(--muted);
}

.lead-agenda-kanban {
  grid-template-columns: repeat(5, minmax(260px, 1fr));
}

.lead-agenda-kanban-column {
  min-width: 260px;
}

.lead-agenda-kanban-list .lead-agenda-item {
  grid-template-columns: 1fr;
}

.lead-agenda-kanban-list .lead-agenda-item-side {
  justify-items: start;
}

.lead-agenda-item-main,
.lead-agenda-item-side {
  min-width: 0;
  display: grid;
  gap: 6px;
}

.lead-agenda-item-main strong,
.lead-agenda-item-main p,
.lead-agenda-item-main small,
.lead-agenda-item-side span {
  min-width: 0;
  overflow-wrap: anywhere;
}

.lead-agenda-item-main p {
  margin: 0;
  color: var(--muted);
}

.lead-agenda-meeting-line {
  color: var(--text);
  font-weight: 700;
}

.lead-client-agenda,
.lead-client-agenda-inline {
  display: grid;
  gap: 12px;
}

.lead-client-agenda-head,
.lead-client-agenda-inline {
  align-items: center;
  justify-content: space-between;
  grid-template-columns: minmax(0, 1fr) auto;
  padding: 12px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.04);
}

.lead-client-agenda-head {
  display: grid;
}

.lead-client-agenda-inline {
  display: grid;
  margin-bottom: 12px;
}

.lead-client-agenda-head small {
  display: block;
  color: var(--muted);
}

.lead-agenda-item-main small {
  color: var(--muted);
}

