.lead-agenda-card .lead-agenda-edit-form label span {
  color: #536171;
  font-weight: 800;
}

.lead-agenda-card .lead-agenda-create-form input,
.lead-agenda-card .lead-agenda-create-form select,
.lead-agenda-card .lead-agenda-create-form textarea,
.lead-agenda-card .lead-agenda-edit-form input,
.lead-agenda-card .lead-agenda-edit-form select,
.lead-agenda-card .lead-agenda-edit-form textarea {
