  min-height: 116px;
  padding: 14px;
  border: 1px solid rgba(15, 23, 42, 0.08);
  background: #ffffff;
}

.lead-agenda-kpi > .material-symbols-outlined {
  position: absolute;
  top: 12px;
  right: 12px;
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 8px;
