  background: #fff1f0;
}

.lead-agenda-kpi.is-today > .material-symbols-outlined {
  color: #1d4ed8;
  background: #eff6ff;
}

.lead-agenda-kpi strong {
  margin-top: 10px;
  color: #111827;
}

.lead-agenda-card .lead-agenda-board {
  margin-top: 4px;
}

.lead-agenda-item {
  position: relative;
  grid-template-columns: 88px minmax(0, 1fr) minmax(168px, auto);
  align-items: stretch;
  padding: 12px;
  border-color: rgba(15, 23, 42, 0.08);
  background: #ffffff;
  box-shadow: 0 10px 26px rgba(15, 23, 42, 0.05);
}

.lead-agenda-item::before {
  content: "";
