  inset: 10px auto 10px 0;
  width: 4px;
  border-radius: 999px;
  background: #0759d6;
}

.lead-agenda-item:has(.priority-urgent)::before {
  background: #dc2626;
}

.lead-agenda-item:has(.priority-high)::before {
  background: #d97706;
}

.lead-agenda-item.is-done::before {
  background: #94a3b8;
}

.lead-agenda-time-block {
  display: grid;
  align-content: center;
  gap: 3px;
  min-width: 0;
  padding: 8px 9px 8px 10px;
  border: 1px solid rgba(15, 23, 42, 0.08);
  border-radius: 8px;
  background: #f8fafc;
}

.lead-agenda-time-block strong {
  color: #111827;
  font-size: 1rem;
}

.lead-agenda-time-block span {
  color: #64748b;
  font-size: 0.75rem;
  line-height: 1.25;
}

.lead-agenda-card .lead-agenda-item-main {
  gap: 7px;
}

.lead-agenda-card .lead-agenda-item-main > strong {
  color: #111827;
  font-size: 1rem;
  line-height: 1.35;
}

.lead-agenda-card .lead-agenda-item-main p {
  display: -webkit-box;
  max-width: 100%;
  margin: 0;
  color: #536171;
  line-height: 1.45;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.lead-agenda-card .lead-agenda-item-main small {
  color: #64748b;
  line-height: 1.35;
}

.lead-agenda-card .lead-agenda-item-side {
  align-content: center;
  gap: 8px;
}

.lead-agenda-card .activation-row-actions {
  justify-content: flex-end;
  gap: 6px;
}

.lead-agenda-card .activation-row-actions .ghost-button,
.lead-agenda-card .activation-row-actions .solid-button {
  min-height: 30px;
  padding: 6px 9px;
  font-size: 0.76rem;
}

.lead-agenda-card .lead-agenda-progress {
  height: 6px;
  background: #e5edf1;
}

.lead-agenda-card .lead-agenda-progress span {
  background: linear-gradient(90deg, #00bfe5, #0ea5e9);
}

.lead-agenda-card .lead-agenda-checklist {
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
}

.lead-agenda-card .lead-agenda-checklist label {
