  background: #f8fafc;
}

.lead-agenda-card .lead-agenda-day-head {
  padding: 4px 2px;
}

.lead-agenda-card .lead-agenda-day-head strong {
  color: #111827;
}

.lead-agenda-card .lead-agenda-hour-row > strong {
  color: #64748b;
}

.lead-agenda-card .lead-agenda-empty-hour {
  border-color: rgba(15, 23, 42, 0.10);
  background: #f8fafc;
  color: #64748b;
}

.lead-agenda-card .lead-agenda-compact-card {
  border-color: rgba(5, 42, 107, 0.18);
  background: #f6fbff;
}

.lead-agenda-card .lead-agenda-compact-main strong {
  color: #111827;
}

.lead-agenda-card .lead-agenda-compact-main span,
.lead-agenda-card .lead-agenda-compact-main small {
