}

.lead-agenda-card .lead-agenda-kanban-head strong,
.lead-agenda-card .lead-week-column-head strong,
.lead-agenda-card .lead-calendar-cell > span,
.lead-agenda-card .lead-year-month strong {
  color: #111827;
}

.lead-agenda-card .lead-agenda-kanban-head span,
.lead-agenda-card .lead-week-column-head span,
.lead-agenda-card .lead-year-month span,
.lead-agenda-card .lead-calendar-cell small {
