.lead-note-form {
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
}

.lead-purchase-form {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  align-items: end;
