}

.lead-purchase-form textarea {
  resize: vertical;
}

.lead-directory-search {
  flex: 1 1 340px;
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 220px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 8px;
  padding: 0 12px;
  background: rgba(255, 255, 255, 0.04);
}

.lead-directory-search input {
  width: 100%;
  min-height: 44px;
  border: 0;
  background: transparent;
  color: inherit;
  outline: 0;
}

.lead-directory-filter-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(150px, 1fr));
  gap: 12px;
}

.lead-directory-filter-grid label {
  display: grid;
  gap: 6px;
}

.lead-directory-row {
  cursor: pointer;
}

.lead-directory-row:hover {
