}

.lead-campaign-chip-list,
.lead-campaign-assign-row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.lead-campaign-assign-row select {
  flex: 1 1 130px;
  min-width: 118px;
  max-width: 100%;
}

.pill .pill-close {
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  font: inherit;
  font-weight: 900;
  line-height: 1;
  padding: 0 0 0 4px;
}

@media (max-width: 980px) {
  .lead-agenda-toolbar {
    grid-template-columns: 1fr;
  }

  .lead-agenda-controls {
    justify-content: flex-start;
  }

  .lead-agenda-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .lead-agenda-create-form {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 680px) {
  .lead-agenda-controls > * {
    flex: 1 1 132px;
  }

  .lead-agenda-kpis {
    grid-template-columns: 1fr;
  }

  .lead-agenda-item {
    grid-template-columns: 1fr;
  }

  .lead-agenda-item-side {
    justify-items: start;
  }

  .lead-agenda-create-form,
  .lead-agenda-edit-form {
    grid-template-columns: 1fr;
  }

  .lead-agenda-create-form .span-2,
  .lead-agenda-edit-form .span-2 {
    grid-column: auto;
  }
}

.lead-attention-board {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 12px;
  margin: 14px 0;
}

.lead-ticket-inventory-board,
.ticket-status-board {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 12px;
  margin: 14px 0;
}

.ticket-status-board {
  grid-template-columns: minmax(0, 1.35fr) minmax(260px, 0.85fr);
  align-items: start;
  margin-top: 0;
  margin-bottom: 16px;
}

.ticket-status-card.is-active {
  grid-row: span 3;
}

.lead-ticket-inventory-card,
.ticket-status-card {
  min-width: 0;
  display: grid;
  gap: 12px;
  padding: 14px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.055), rgba(255, 255, 255, 0.028)),
    rgba(8, 18, 28, 0.62);
}

.lead-ticket-inventory-card.is-active,
.ticket-status-card.is-active {
