.lead-ticket-inventory-card.is-inactive,
.ticket-status-card.is-inactive {
  border-color: rgba(250, 204, 21, 0.28);
  background: rgba(250, 204, 21, 0.07);
}

.lead-ticket-inventory-head,
.ticket-status-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 4px 12px;
  align-items: start;
