}

.lead-workspace-head p {
  margin: 0;
  color: var(--muted);
}

.lead-detail-shell .lead-detail-card {
  width: min(1180px, calc(100vw - 28px));
  max-height: min(92vh, 980px);
  overflow: auto;
}

.lead-profile-header {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(360px, 0.8fr);
  gap: 18px;
  padding: 18px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.035);
}

.lead-identity-block,
.lead-decision-panel,
.lead-health-card,
.lead-next-actions {
  display: grid;
  gap: 12px;
}

.lead-status-row,
.lead-contact-strip,
.lead-funnel-strip,
.lead-analysis-tags {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  align-items: center;
}

.lead-profile-header h4 {
  margin: 10px 0 6px;
  font-size: clamp(1.6rem, 2.4vw, 2.5rem);
}

.lead-profile-header p {
  margin: 0;
  color: var(--muted);
}

.lead-contact-strip span,
.lead-analysis-tags span {
  display: grid;
  gap: 2px;
  min-width: 142px;
  padding: 9px 10px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.04);
  color: var(--muted);
}

.lead-contact-strip strong {
  color: var(--text);
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0;
}

.lead-funnel-strip {
  padding-top: 4px;
}

.lead-funnel-strip span {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  padding: 7px 10px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.035);
}

.lead-funnel-strip span.is-done {
  border-color: rgba(0, 191, 229, 0.28);
  color: var(--text);
  background: rgba(0, 191, 229, 0.1);
}

.lead-funnel-strip.wide {
  gap: 10px;
}

.lead-header-metrics,
.lead-summary-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.lead-health-card {
  padding: 14px;
  border: 1px solid rgba(0, 191, 229, 0.2);
  border-radius: 8px;
  background: rgba(0, 191, 229, 0.07);
}

.lead-health-card strong {
  font-size: 2rem;
}

.lead-health-card small {
  color: var(--muted);
}

.lead-health-bar {
  height: 9px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.09);
}

.lead-health-bar span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #facc15, #00bfe5);
}

.lead-next-actions {
  grid-template-columns: 1fr;
}

.lead-action-tile,
.lead-action-card {
  display: grid;
  gap: 4px;
