}

.lead-action-tile {
  padding: 10px 12px;
}

.lead-action-card {
  min-height: 132px;
  padding: 14px;
}

.lead-action-tile span,
.lead-action-card p {
  margin: 0;
  color: var(--muted);
}

.lead-action-tile.is-ok,
.lead-action-card.is-ok {
  border-color: rgba(0, 191, 229, 0.25);
}

.lead-action-tile.is-warning,
.lead-action-card.is-warning {
  border-color: rgba(250, 204, 21, 0.3);
}

.lead-action-tile.is-danger,
.lead-action-card.is-danger {
  border-color: rgba(251, 113, 133, 0.32);
}

.lead-action-tile:hover,
.lead-action-card:hover {
