}

.lead-tabs {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 4px;
  scroll-snap-type: x proximity;
  scrollbar-width: thin;
}

.lead-tabs .segment-tab {
  flex: 0 0 auto;
  min-height: 38px;
  white-space: nowrap;
