}

.lead-ticket-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 12px;
}

.lead-ticket-card {
  min-width: 0;
  display: grid;
  gap: 12px;
  padding: 12px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.04);
}

.lead-ticket-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 10px;
}

.lead-ticket-head small {
  display: block;
  margin-top: 3px;
  color: var(--muted);
}

.lead-ticket-origin {
  display: grid;
  gap: 4px;
  padding: 10px;
  border: 1px solid rgba(229, 251, 255, 0.16);
  border-radius: 8px;
  background: rgba(229, 251, 255, 0.06);
}

.lead-ticket-origin strong {
