  gap: 2px;
  padding: 8px;
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.04);
  color: var(--muted);
  overflow-wrap: anywhere;
}

.lead-ticket-meta strong {
  color: var(--text);
  font-size: 0.7rem;
  text-transform: uppercase;
}

.lead-interest-pill {
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 999px;
  padding: 8px 10px;
  background: rgba(255, 255, 255, 0.06);
  color: inherit;
  cursor: pointer;
}

.lead-interest-pill span {
  color: var(--muted);
