}

.lead-activation-result {
  margin-top: 12px;
}

.lead-capture-card {
  display: grid;
  gap: 18px;
  border-color: rgba(232, 193, 112, 0.22);
  background: linear-gradient(180deg, rgba(232, 193, 112, 0.08), rgba(255, 255, 255, 0.035));
}

.lead-capture-form {
  display: grid;
  gap: 16px;
}

.lead-capture-fieldset {
  display: grid;
  gap: 12px;
  padding: 14px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  background: rgba(7, 16, 23, 0.28);
}

.lead-capture-fieldset legend {
  padding: 0 6px;
  color: var(--text);
