}

#leadCaptureFieldsGrid,
.lead-capture-fields-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
  gap: 10px;
}

.lead-capture-field-row {
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: center;
  gap: 10px;
  min-height: 46px;
  padding: 10px;
