}

.lead-capture-content-editor {
  padding: 14px;
  border: 1px solid rgba(229, 251, 255, 0.18);
  border-radius: 8px;
  background: rgba(229, 251, 255, 0.055);
}

.digital-assets-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 12px;
  margin-top: 14px;
}

.digital-asset-card,
.digital-asset-selected {
  display: grid;
  grid-template-columns: 76px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  padding: 12px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.04);
}

.digital-asset-card {
  grid-template-columns: 76px minmax(0, 1fr);
}

.digital-asset-card.is-editing {
  border-color: rgba(229, 251, 255, 0.36);
  background: rgba(229, 251, 255, 0.055);
}

.digital-asset-card .activation-row-actions {
  grid-column: 1 / -1;
}

.digital-asset-card img,
.digital-asset-selected img {
  width: 76px;
  height: 76px;
  object-fit: cover;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.08);
}

.digital-asset-card > .material-symbols-outlined,
.digital-asset-selected > .material-symbols-outlined {
  width: 76px;
  height: 76px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  background: rgba(0, 191, 229, 0.08);
  color: var(--text);
}

.digital-asset-card p,
.digital-asset-selected p {
  margin: 4px 0;
  color: var(--muted);
}

.digital-asset-card small,
.digital-asset-selected small {
  color: var(--muted);
}

.digital-asset-edit-note {
  display: block;
  margin-top: 6px;
  color: var(--secondary-soft) !important;
  font-weight: 800;
  line-height: 1.35;
}

.digital-asset-share-link,
.digital-asset-share-note {
  display: block;
  margin-top: 8px;
  overflow-wrap: anywhere;
}

.digital-asset-share-link {
  color: var(--secondary-soft);
  font-size: 12px;
  font-weight: 800;
  text-decoration: none;
}

.digital-asset-share-note {
  font-size: 12px;
  line-height: 1.35;
}

.digital-asset-edit-form,
.digital-asset-landings {
  grid-column: 1 / -1;
}

.digital-asset-edit-form {
  padding: 12px;
  border: 1px solid rgba(229, 251, 255, 0.18);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.12);
}

.digital-asset-landing-template {
  display: grid;
  gap: 4px;
  padding: 10px 12px;
  border: 1px solid rgba(229, 251, 255, 0.18);
  border-radius: 8px;
  background: rgba(229, 251, 255, 0.07);
}

.digital-asset-landing-template span {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.4;
}

.digital-asset-landings {
  display: grid;
  gap: 10px;
  padding-top: 4px;
}

.digital-asset-landings-head,
.digital-asset-landing-row,
.digital-asset-landing-empty {
  display: flex;
  gap: 10px;
  align-items: center;
  justify-content: space-between;
}

.digital-asset-landings-head span,
.digital-asset-landing-row p,
.digital-asset-landing-empty span {
  color: var(--muted);
  font-size: 12px;
}

.digital-asset-landing-row,
.digital-asset-landing-empty {
  padding: 10px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.035);
}

.digital-asset-landing-row > div:first-child {
  min-width: 0;
}

.digital-asset-landing-row p {
  margin: 3px 0;
}

.lead-capture-asset-preview {
  display: grid;
  gap: 8px;
}

.lead-capture-metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 12px;
}

.qr-result {
  display: grid;
  gap: 10px;
  padding: 14px;
  border: 1px solid rgba(232, 193, 112, 0.25);
  border-radius: 8px;
  background: rgba(232, 193, 112, 0.08);
}

.qr-preview {
  width: min(220px, 100%);
  aspect-ratio: 1;
  border-radius: 8px;
  background: #fff;
  padding: 10px;
}

.activation-row-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

@media (max-width: 980px) {
  .contact-center-operator-panel,
  .contact-center-tabs,
  .contact-action-item,
  .lead-directory-filter-grid,
  .lead-profile-header,
  .lead-header-metrics,
  .lead-summary-grid,
  .lead-ticket-summary,
  .lead-ticket-meta,
  .lead-analysis-grid,
  .lead-purchase-form,
  .lead-capture-field-row {
    grid-template-columns: 1fr;
  }

  .lead-purchase-form > div:first-child,
  .lead-purchase-form .span-2 {
    grid-column: auto;
  }

  .contact-center-stage-actions,
  .contact-action-side {
    justify-content: flex-start;
    justify-items: start;
  }

  .lead-detail-workspace {
    padding: 14px;
  }
}

/* Global UX hardening: keep complex portal modules contained and scrollable. */
html,
body,
.portal-shell,
.app-shell,
.app-main,
.content-shell {
  max-width: 100%;
}

.content-shell,
.view-section,
.surface-card,
.data-table-card,
.chart-card,
.table-card,
.modal-card,
.contact-center-shell,
.lead-detail-workspace {
  min-width: 0;
}

.view-section :where(.surface-card, .data-table-card, .chart-card, .table-card, .campaign-item, .contact-action-item, .mission-active-card, .rms-opportunity-card, .affiliate-panel, .account-profile-card) {
  overflow-wrap: anywhere;
}

.view-section :where(.table-wrap, .compact-table, .rms-stage-board, .rms-daily-queue, .ticket-flow-track, .contact-center-tabs) {
  max-width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior-x: contain;
}

.view-section :where(canvas, img, video, svg) {
  max-width: 100%;
}

.view-section :where(input, select, textarea) {
  max-width: 100%;
  min-width: 0;
}

.view-section :where(button, .solid-button, .ghost-button, .danger-button) {
  min-width: 0;
}

.modal-shell {
  align-items: start;
}

.modal-shell .modal-card {
  margin-block: auto;
}

@media (max-width: 720px) {
  .modal-shell {
    padding: 12px;
  }

  .modal-shell .modal-card {
    width: 100%;
    max-width: 100%;
    max-height: calc(100dvh - 24px);
    border-radius: 14px;
    padding: 14px;
  }

  .modal-head h3 {
    font-size: 22px;
  }

  .nav-item {
    min-height: 40px;
  }
}

/* Sidebar fit hardening: feature labels must remain readable instead of clipped. */
.sidebar {
  scrollbar-gutter: stable;
}

.sidebar-brand,
.sidebar-brand div,
.sidebar-nav,
.nav-item {
  min-width: 0;
}

.sidebar-brand h1,
.sidebar-brand p,
.nav-group-label,
.nav-item span:last-child {
  overflow-wrap: anywhere;
}

.nav-item {
  height: auto;
  align-items: flex-start;
  overflow: visible;
}

.nav-item span:last-child {
  flex: 1 1 auto;
  min-width: 0;
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
}

.app-shell.sidebar-collapsed .nav-item {
  align-items: center;
  overflow: hidden;
}

.app-shell.sidebar-collapsed .nav-item span:last-child {
  display: none;
}

@media (max-width: 960px) {
  .sidebar {
    width: min(88vw, 348px);
  }
}

/* Portal organization layer: turn many modules into one guided revenue journey. */
.sidebar-flow-card {
  display: grid;
  gap: 7px;
  margin-top: 16px;
  padding: 12px;
  border: 1px solid rgba(0, 229, 255, 0.2);
  border-radius: 10px;
  background:
    linear-gradient(135deg, rgba(0, 229, 255, 0.1), rgba(0, 191, 229, 0.06)),
    rgba(3, 11, 27, 0.48);
  color: #e9fbff;
  min-width: 0;
}

.sidebar-flow-card strong,
.sidebar-flow-card small {
  display: block;
  min-width: 0;
  overflow-wrap: anywhere;
}

.sidebar-flow-card strong {
  font-size: 13px;
  line-height: 1.25;
}

.sidebar-flow-card small {
  color: rgba(233, 251, 255, 0.7);
  font-size: 11px;
  line-height: 1.35;
}

.sidebar-flow-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
  margin-top: 4px;
}

.sidebar-flow-actions button {
  min-width: 0;
  border: 1px solid rgba(0, 229, 255, 0.2);
  border-radius: 7px;
  background: rgba(0, 229, 255, 0.08);
  color: #e9fbff;
  font-size: 11px;
  font-weight: 800;
  padding: 7px 6px;
  cursor: pointer;
}

.sidebar-flow-actions button:hover {
  background: rgba(0, 191, 229, 0.13);
  border-color: rgba(0, 191, 229, 0.32);
}

.app-shell.sidebar-collapsed .sidebar-flow-card {
  display: none;
}

.portal-module-map {
  display: grid;
  gap: 14px;
  border: 1px solid rgba(5, 42, 107, 0.18);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.72);
  padding: 16px;
}

.portal-map-head {
  display: grid;
  grid-template-columns: minmax(240px, 0.9fr) minmax(260px, 1.1fr);
  gap: 12px;
  align-items: end;
}

.portal-map-head h3,
.portal-map-head p {
  margin: 0;
}

.portal-map-head h3 {
  margin-top: 5px;
  color: var(--primary);
}

.portal-map-head p {
  color: var(--text-muted);
  line-height: 1.45;
}

.portal-map-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.portal-map-grid article {
  display: grid;
  gap: 9px;
  align-content: start;
  min-width: 0;
  min-height: 192px;
  padding: 14px;
  border: 1px solid var(--surface-border);
  border-radius: 8px;
  background: var(--surface);
}

.portal-map-grid .material-symbols-outlined {
  color: var(--secondary);
  font-size: 28px;
}

.portal-map-grid h4,
.portal-map-grid p {
  margin: 0;
}

.portal-map-grid h4 {
  color: var(--primary);
  line-height: 1.25;
}

.portal-map-grid p {
  color: var(--text-muted);
  line-height: 1.45;
}

.portal-map-grid .button-row {
  margin-top: auto;
}

.portal-map-grid .ghost-button {
  padding: 8px 10px;
  min-height: 34px;
}

@media (max-width: 1180px) {
  .portal-map-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .portal-map-head,
  .portal-map-grid {
    grid-template-columns: 1fr;
  }

  .portal-module-map {
    padding: 12px;
  }

  .portal-map-grid article {
    min-height: 0;
  }
}

/* Sidebar reachability: keep every left-menu option accessible on short screens. */
.sidebar {
  height: 100vh;
  height: 100dvh;
  max-height: 100dvh;
  overflow: hidden;
}

.sidebar-brand,
.sidebar-flow-card {
  flex: 0 0 auto;
}

.sidebar-nav {
  flex: 1 1 auto;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  padding-right: 4px;
  margin-right: -4px;
  scrollbar-gutter: stable;
}

.sidebar-nav::-webkit-scrollbar {
  width: 8px;
}

.sidebar-nav::-webkit-scrollbar-track {
  background: transparent;
}

.sidebar-nav::-webkit-scrollbar-thumb {
  background: rgba(0, 229, 255, 0.22);
  border-radius: 999px;
}

.sidebar-nav:hover::-webkit-scrollbar-thumb {
  background: rgba(0, 191, 229, 0.34);
}

@media (max-height: 760px) and (min-width: 961px) {
  .sidebar {
