  margin-inline: auto;
}

.view-section {
  width: 100%;
}

.view-head,
.card-head,
.table-card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
}

.view-head > div:first-child,
.card-head > div:first-child,
.table-card-head > div:first-child {
