/* Object fit and margin refinement: calmer rhythm across dense portal modules. */
:root {
  --page-gutter: clamp(18px, 2vw, 34px);
  --section-gap: clamp(18px, 1.7vw, 28px);
  --card-padding: clamp(16px, 1.35vw, 24px);
  --card-gap: clamp(12px, 1.2vw, 18px);
}

/* Portal task-first navigation: four direct outcomes, everything else on demand. */
.sidebar-nav > .nav-item > span:last-child {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.sidebar-nav > .nav-item > span:last-child strong,
.sidebar-nav > .nav-item > span:last-child small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

