  color: rgba(234, 244, 255, 0.7) !important;
  font-size: 10px;
  font-weight: 650;
}

.portal-more-nav {
  margin-top: 4px;
  border: 1px solid rgba(233, 204, 139, 0.2);
  background: rgba(0, 0, 0, 0.12);
}

.portal-more-nav > summary {
  min-height: 44px;
  display: grid;
  grid-template-columns: 28px 1fr 22px;
  align-items: center;
  gap: 8px;
  padding: 9px 11px;
  color: #e5fbff;
  cursor: pointer;
  font-size: 12px;
  font-weight: 850;
  list-style: none;
}

.portal-more-nav > summary::-webkit-details-marker { display: none; }
.portal-more-nav > summary .material-symbols-outlined { color: #d8b96c; font-size: 20px; }
.portal-more-nav > summary .material-symbols-outlined:last-child { transition: transform 160ms ease; }
.portal-more-nav[open] > summary .material-symbols-outlined:last-child { transform: rotate(180deg); }

.portal-more-nav-list {
  display: grid;
  gap: 6px;
  padding: 5px 7px 9px;
  border-top: 1px solid rgba(233, 204, 139, 0.16);
}

.portal-more-nav-list .nav-group-label { margin: 8px 4px 2px; }
.portal-more-nav-list .nav-item { width: 100%; }

.purchase-period-actions {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  margin-top: 18px;
}

.purchase-period-actions button {
  min-height: 48px;
}

.mission-rank-row.is-purchase-ranking {
  grid-template-columns: 38px minmax(120px, 1fr) minmax(110px, auto);
  align-items: center;
}

.mission-rank-customer,
.mission-rank-result {
  display: grid;
  gap: 2px;
}

.mission-rank-result {
  text-align: right;
}

.mission-rank-result strong {
  color: var(--accent, #052a6b);
}

@media (max-width: 760px) {
  .purchase-period-actions { grid-template-columns: 1fr 1fr; }
  .mission-rank-row.is-purchase-ranking { grid-template-columns: 34px 1fr; }
  .mission-rank-result { grid-column: 2; text-align: left; }
}

