  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-width: 0;
}

.commerce-feed-head strong {
  color: #071832;
  overflow-wrap: anywhere;
}

.commerce-feed-step {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 10px;
  border: 1px solid #d8e6f2;
  border-radius: 8px;
  background: #ffffff;
  min-width: 0;
}

.commerce-feed-step > .material-symbols-outlined {
  color: #53677f;
  font-size: 22px;
}

.commerce-feed-step strong {
  display: block;
  color: #071832;
  overflow-wrap: anywhere;
}

.commerce-feed-step p {
  margin: 3px 0 0;
  color: #53677f;
  line-height: 1.42;
  overflow-wrap: anywhere;
}

.commerce-feed-step.is-done {
  border-color: #e5fbff;
  background: #f6fbff;
}

.commerce-feed-step.is-done > .material-symbols-outlined {
  color: #0759d6;
}

.commerce-feed-step.is-active {
  border-color: #dec77a;
  background: #fffaf0;
}

.commerce-feed-step.is-active > .material-symbols-outlined {
  color: #9a741c;
}

.commerce-feed-step.is-pending {
  opacity: 0.86;
}

.commerce-feed-shortcuts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

.rms-stage-column,
.rms-opportunity-card,
.lead-agenda-item,
.mission-active-card,
.affiliate-purchase-item,
.sales-item-row {
  transition: transform 140ms ease, box-shadow 140ms ease, border-color 140ms ease !important;
}

.rms-opportunity-card:hover,
.lead-agenda-item:hover,
.mission-active-card:hover,
.affiliate-purchase-item:hover,
.sales-item-row:hover {
  transform: translateY(-1px) !important;
  box-shadow: 0 12px 22px rgba(5, 42, 107, 0.085) !important;
}

