/* Dashboard builder */
.dashboard-builder-mode > :where(.revenue-workspace, .command-center-shell, .business-kpis, .explain-grid, .dashboard-charts, .insight-grid, .data-table-card) {
  display: none !important;
}

.dashboard-builder-shell {
  display: grid;
  gap: 18px;
  margin-bottom: 24px;
}

.dashboard-builder-head,
.dashboard-builder-layout,
.dashboard-canvas-head {
  display: grid;
  gap: 16px;
}

.dashboard-builder-head {
  grid-template-columns: minmax(0, 1.1fr) auto;
  align-items: start;
  padding: 18px;
  border: 1px solid rgba(5, 42, 107, 0.16);
  border-radius: 14px;
  background: linear-gradient(135deg, #ffffff, #f6fbff);
  box-shadow: 0 18px 42px rgba(5, 42, 107, 0.08);
}

.dashboard-builder-head h3,
.dashboard-canvas-head h3,
.dashboard-widget-library h4 {
  margin: 4px 0 6px;
  color: var(--primary);
}

.dashboard-builder-head p,
.dashboard-canvas-head p,
.dashboard-widget-library p,
.dashboard-widget-meta,
.dashboard-widget-body,
.dashboard-mini-empty,
.dashboard-builder-empty p {
  margin: 0;
  color: var(--muted);
  line-height: 1.45;
}

.dashboard-profile-tabs {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
  align-items: center;
}

.dashboard-profile-tabs button,
.dashboard-library-item {
  border: 1px solid rgba(5, 42, 107, 0.16);
  background: #ffffff;
  color: var(--text);
  border-radius: 10px;
  cursor: pointer;
  transition: border-color var(--motion-fast) ease, box-shadow var(--motion-fast) ease, transform var(--motion-fast) ease;
}

.dashboard-profile-tabs button {
  min-height: 40px;
  padding: 0 14px;
  font-weight: 800;
}

.dashboard-profile-tabs button.active,
.dashboard-profile-tabs button:hover {
  border-color: rgba(5, 42, 107, 0.44);
  box-shadow: 0 10px 24px rgba(5, 42, 107, 0.12);
}

.dashboard-builder-layout {
  grid-template-columns: minmax(240px, 300px) minmax(0, 1fr);
  align-items: start;
}

.dashboard-widget-library,
.dashboard-canvas,
.dashboard-widget-card,
.dashboard-builder-empty {
  border: 1px solid rgba(15, 23, 42, 0.08);
  background: #ffffff;
  box-shadow: 0 16px 38px rgba(15, 23, 42, 0.07);
}

.dashboard-widget-library,
.dashboard-canvas {
  border-radius: 14px;
  padding: 16px;
}

.dashboard-widget-library {
  position: sticky;
  top: 88px;
  display: grid;
  gap: 14px;
  max-height: calc(100vh - 120px);
  overflow: auto;
}

.dashboard-widget-library-list {
  display: grid;
  gap: 10px;
}

.dashboard-library-item {
  width: 100%;
  min-height: 62px;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 10px;
  text-align: left;
}

.dashboard-library-item:hover,
.dashboard-library-item.is-active {
  border-color: rgba(5, 42, 107, 0.36);
  box-shadow: 0 12px 28px rgba(5, 42, 107, 0.1);
  transform: translateY(-1px);
}

.dashboard-library-item .material-symbols-outlined {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: #e5fbff;
  color: var(--primary);
}

.dashboard-library-item strong,
.dashboard-library-item small,
.dashboard-library-item em {
  display: block;
}

.dashboard-library-item strong,
.dashboard-widget-top h4 {
  color: var(--text);
}

.dashboard-library-item small,
.dashboard-library-item em {
  color: var(--muted);
  font-style: normal;
  font-size: 0.78rem;
}

.dashboard-canvas {
  display: grid;
  gap: 16px;
  min-width: 0;
}

.dashboard-canvas-head {
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  padding-bottom: 14px;
  border-bottom: 1px solid rgba(15, 23, 42, 0.08);
}

.dashboard-canvas-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.dashboard-canvas-actions .ghost-button.active {
  border-color: rgba(5, 42, 107, 0.38);
  background: #e5fbff;
  color: var(--primary);
}

.dashboard-widget-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
  align-items: stretch;
}

.dashboard-widget-card,
.dashboard-builder-empty {
  min-width: 0;
  border-radius: 12px;
  padding: 14px;
}

.dashboard-widget-card {
  min-height: 236px;
  display: grid;
  grid-template-rows: auto auto auto minmax(54px, 1fr) auto;
  gap: 10px;
  cursor: grab;
}

.dashboard-widget-card.is-dragging {
  opacity: 0.58;
  outline: 2px dashed rgba(5, 42, 107, 0.35);
}

.dashboard-widget-card.action {
  border-color: rgba(5, 42, 107, 0.24);
  background: linear-gradient(180deg, #ffffff, #e5fbff);
}

.dashboard-widget-card.money {
  border-color: rgba(7, 89, 214, 0.22);
}

.dashboard-widget-card.chart {
  grid-column: span 2;
}

.dashboard-widget-card.table {
  grid-column: span 2;
}

.dashboard-widget-top {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) 34px;
  gap: 10px;
  align-items: start;
}

.dashboard-widget-top h4 {
  margin: 2px 0 0;
  font-size: 1rem;
}

.dashboard-widget-icon {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: #f6fbff;
  color: var(--primary);
}

.dashboard-widget-value {
  display: block;
  color: var(--primary);
  font-size: clamp(1.32rem, 1.8vw, 1.9rem);
  line-height: 1.1;
  word-break: break-word;
}

.dashboard-widget-body {
  font-size: 0.9rem;
}

.dashboard-widget-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.dashboard-widget-actions .ghost-button {
  flex: 1 1 150px;
  justify-content: center;
}

.dashboard-mini-bars {
  display: grid;
  gap: 8px;
}

.dashboard-mini-bar {
  display: grid;
  gap: 4px;
}

.dashboard-mini-bar-top {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  color: var(--text);
  font-size: 0.84rem;
}

.dashboard-mini-bar-top span,
.dashboard-mini-bar small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-mini-bar-top strong {
  flex: 0 0 auto;
  color: var(--primary);
}

.dashboard-mini-bar i {
  display: block;
  height: 8px;
  overflow: hidden;
  border-radius: 999px;
  background: #edf2f7;
}

.dashboard-mini-bar b {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #0759d6, #00bfe5);
}

.dashboard-mini-bar small {
  color: var(--muted);
  font-size: 0.76rem;
}

.dashboard-funnel-simple {
  display: grid;
  gap: 10px;
}

.dashboard-funnel-row {
  display: grid;
  grid-template-columns: minmax(78px, 0.8fr) minmax(90px, 1.4fr) auto minmax(60px, 0.7fr);
  gap: 8px;
  align-items: center;
  font-size: 0.84rem;
}

.dashboard-funnel-row span,
.dashboard-funnel-row small {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-funnel-row span {
  color: var(--text);
  font-weight: 800;
}

.dashboard-funnel-row small {
  color: var(--muted);
}

.dashboard-funnel-row strong {
  color: var(--primary);
  font-variant-numeric: tabular-nums;
}

.dashboard-funnel-row i {
  display: block;
  height: 10px;
  overflow: hidden;
  border-radius: 999px;
  background: #edf2f7;
}

.dashboard-funnel-row b {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #0759d6, #00bfe5);
}

.dashboard-roi-table-wrap {
  width: 100%;
  overflow: auto;
  border: 1px solid rgba(15, 23, 42, 0.08);
  border-radius: 10px;
}

.dashboard-roi-table {
  width: 100%;
  min-width: 520px;
  border-collapse: collapse;
  font-size: 0.82rem;
}

.dashboard-roi-table th,
.dashboard-roi-table td {
  padding: 8px 10px;
  text-align: left;
  border-bottom: 1px solid rgba(15, 23, 42, 0.07);
  color: var(--text);
  white-space: nowrap;
}

.dashboard-roi-table th {
  background: #f8fafc;
  color: var(--muted);
  font-size: 0.72rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.dashboard-roi-table tr:last-child td {
  border-bottom: 0;
}

.dashboard-builder-empty {
  grid-column: 1 / -1;
  min-height: 180px;
  display: grid;
  place-items: center;
  text-align: center;
  gap: 8px;
}

.dashboard-builder-empty .material-symbols-outlined {
  font-size: 36px;
  color: var(--primary);
}

@media (max-width: 1180px) {
  .dashboard-builder-head,
  .dashboard-builder-layout,
  .dashboard-canvas-head {
    grid-template-columns: 1fr;
  }

  .dashboard-profile-tabs,
  .dashboard-canvas-actions {
    justify-content: flex-start;
  }

  .dashboard-widget-library {
    position: static;
    max-height: none;
  }
}

@media (max-width: 980px) {
  .dashboard-widget-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 700px) {
  .dashboard-widget-grid {
    grid-template-columns: 1fr;
  }

  .dashboard-widget-card.chart {
    grid-column: auto;
  }

  .dashboard-widget-card.table {
    grid-column: auto;
  }

  .dashboard-funnel-row {
    grid-template-columns: minmax(68px, 0.8fr) minmax(80px, 1.2fr) auto;
  }

  .dashboard-funnel-row small {
    grid-column: 2 / -1;
  }
}

