.rms-operator-toolbar {
  display: grid !important;
  grid-template-columns: minmax(240px, 1.3fr) repeat(3, minmax(160px, 0.8fr)) auto;
  gap: 12px;
  align-items: end;
  border-radius: 14px !important;
}

.rms-operator-toolbar > div {
  display: grid;
  gap: 4px;
}

.rms-operator-toolbar label {
  display: grid;
  gap: 6px;
}

.rms-intake-funnel-shell,
.rms-industrial-flow-shell,
.rms-event-log-shell {
  border-radius: 14px !important;
}

.rms-intake-funnel {
  display: grid;
  grid-template-columns: repeat(5, minmax(150px, 1fr));
  gap: 10px;
  overflow-x: auto;
}

.rms-funnel-step {
  position: relative;
  min-width: 150px;
  min-height: 132px;
  display: grid;
  gap: 6px;
  align-content: start;
  padding: 14px;
  border: 1px solid #eaf4ff;
  border-radius: 12px;
  background: #f8fbff;
}

.rms-funnel-step::after {
  content: "";
  position: absolute;
  right: -9px;
  top: 50%;
  width: 18px;
  height: 2px;
  background: #e5fbff;
}

.rms-funnel-step:last-child::after {
  display: none;
}

.rms-funnel-step span {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  color: #ffffff;
  background: #0759d6;
  font-weight: 900;
  font-size: 0.78rem;
}

.rms-funnel-step strong {
  font-size: clamp(26px, 3vw, 40px);
  color: #071832;
  line-height: 1;
}

.rms-funnel-step h4 {
  margin: 0;
  color: #071832;
}

.rms-funnel-step p {
  margin: 0;
  color: #53677f;
  line-height: 1.35;
}

.rms-industrial-flow {
  display: grid;
  grid-template-columns: repeat(12, minmax(240px, 1fr));
  gap: 10px;
  overflow-x: auto;
  padding-bottom: 4px;
  scrollbar-width: thin;
}

.rms-industrial-step {
  position: relative;
  min-width: 240px;
  display: grid;
  grid-template-rows: auto minmax(116px, 1fr) auto auto;
  gap: 10px;
  padding: 14px;
  border: 1px solid #d8e6f2;
  border-radius: 12px;
  background: linear-gradient(180deg, #ffffff, #f6fbff);
  box-shadow: 0 10px 22px rgba(5, 42, 107, 0.055);
}

.rms-industrial-step::after {
  content: "";
  position: absolute;
  right: -9px;
  top: 32px;
  width: 18px;
  height: 2px;
  background: #e5fbff;
}

.rms-industrial-step:last-child::after {
  display: none;
}

.rms-industrial-step > span {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  color: #ffffff;
  background: linear-gradient(135deg, #0759d6, #2875a6);
  font-size: 0.8rem;
  font-weight: 900;
}

.rms-industrial-step strong {
  display: block;
  color: #071832;
  font-size: 1rem;
}

.rms-industrial-step p {
  margin: 5px 0 0;
  color: #53677f;
  line-height: 1.35;
}

.rms-industrial-step dl {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
  margin: 0;
}

.rms-industrial-step dl div {
  display: grid;
  gap: 2px;
  min-width: 0;
  padding: 7px;
  border: 1px solid #d8e6f2;
  border-radius: 9px;
  background: #ffffff;
}

.rms-industrial-step dt {
  color: #53677f;
  font-size: 0.68rem;
  font-weight: 850;
}

.rms-industrial-step dd {
  margin: 0;
  color: #071832;
  font-size: 0.82rem;
  font-weight: 900;
}

.rms-alert-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));
  gap: 12px;
}

.rms-alert-card {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  padding: 14px;
  border: 1px solid #efd094;
  border-left: 5px solid #d99a25;
  border-radius: 12px;
  background: #fffbef;
  box-shadow: 0 12px 28px rgba(92, 67, 16, 0.06);
}

.rms-alert-card > .material-symbols-outlined {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  color: #7a4e07;
  background: #fff4cf;
}

.rms-alert-card strong {
  color: #352608;
}

.rms-alert-card p {
  margin: 3px 0 0;
  color: #6b5424;
}

.rms-bulk-toolbar {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) minmax(160px, 0.6fr) auto auto auto;
  gap: 10px;
  align-items: center;
  margin-bottom: 12px;
  padding: 12px;
  border: 1px solid #d8e6f2;
  border-radius: 12px;
  background: #f6fbff;
}

.rms-bulk-toolbar.has-selection {
  border-color: #0759d6;
  background: #f6fbff;
  box-shadow: 0 12px 28px rgba(7, 89, 214, 0.1);
}

.rms-bulk-toolbar > div {
  display: grid;
  gap: 2px;
}

.rms-bulk-toolbar small {
  color: #53677f;
}

.rms-stage-board {
  grid-template-columns: repeat(11, minmax(280px, 1fr)) !important;
  align-items: stretch;
  gap: 12px !important;
}

.rms-stage-column {
  min-width: 280px !important;
  display: grid;
  grid-template-rows: auto auto minmax(120px, 1fr);
  gap: 10px;
  border-radius: 14px !important;
  border-color: #d8e6f2 !important;
  background: #ffffff !important;
}

.rms-stage-head {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) auto !important;
  align-items: start !important;
  gap: 10px !important;
  padding-bottom: 10px;
  border-bottom: 1px solid #eaf4ff;
}

.rms-stage-head strong {
  display: block;
  margin-top: 3px;
  font-size: 1.12rem;
  color: #071832;
}

.rms-stage-head > span {
  min-width: 42px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  color: #ffffff;
  background: #0759d6;
  font-weight: 900;
}

.rms-phase-operation {
  display: grid;
  gap: 7px;
  padding: 11px;
  border: 1px solid #eaf4ff;
  border-radius: 11px;
  background: #f6fbff;
}

.rms-phase-operation strong {
  color: #071832;
}

.rms-phase-operation small {
  color: #53677f;
}

.rms-stage-items {
  display: grid;
  gap: 9px;
  align-content: start;
}

.rms-lead-unit {
  position: relative;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 8px;
  padding: 10px;
  border: 1px solid #d8e6f2;
  border-radius: 12px;
  background: #f8fbff;
  transition: border-color 0.16s ease, background 0.16s ease, box-shadow 0.16s ease;
}

.rms-lead-unit.selected {
  border-color: #0759d6;
  background: #f6fbff;
  box-shadow: inset 0 0 0 1px rgba(7, 89, 214, 0.14);
}

.rms-unit-selector {
  grid-row: span 3;
  align-self: start;
  padding-top: 2px;
}

.rms-unit-selector input {
  width: 18px !important;
  height: 18px;
  accent-color: #0759d6;
}

.rms-unit-main {
  display: grid;
  gap: 4px;
  min-width: 0;
  border: 0;
  padding: 0;
  color: inherit;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.rms-unit-main strong,
.rms-unit-main small,
.rms-unit-main em {
  display: block;
  min-width: 0;
}

.rms-unit-main strong {
  color: #071832;
}

.rms-unit-main small {
  color: #53677f;
}

.rms-unit-main em {
  color: #052a6b;
  font-style: normal;
  font-weight: 850;
}

.rms-unit-meta,
.rms-unit-actions {
  grid-column: 2;
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  align-items: center;
}

.rms-unit-meta span:not(.status-chip) {
  padding: 4px 7px;
  border: 1px solid #d8e6f2;
  border-radius: 999px;
  color: #53677f;
  background: #ffffff;
  font-size: 0.74rem;
  font-weight: 800;
}

.rms-unit-actions {
  justify-content: flex-end;
}

.rms-lead-inspector {
  position: sticky;
  bottom: 14px;
  z-index: 20;
  margin-left: auto;
  width: min(100%, 980px);
  display: grid;
  gap: 14px;
  border-radius: 14px !important;
  border-color: #b8d2e9 !important;
  box-shadow: 0 22px 52px rgba(5, 42, 107, 0.16) !important;
}

.rms-lead-inspector.hidden {
  display: none;
}

.rms-inspector-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: start;
  padding-bottom: 12px;
  border-bottom: 1px solid #eaf4ff;
}

.rms-inspector-head h3 {
  margin: 4px 0;
  color: #071832;
  font-size: clamp(22px, 2.6vw, 34px);
}

.rms-inspector-head p {
  margin: 0;
  color: #53677f;
}

.rms-inspector-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 10px;
}

.rms-inspector-grid > div {
  display: grid;
  gap: 4px;
  padding: 11px;
  border: 1px solid #d8e6f2;
  border-radius: 10px;
  background: #f6fbff;
}

.rms-inspector-grid span {
  color: #53677f;
  font-size: 0.76rem;
  font-weight: 850;
}

.rms-inspector-operation {
  display: grid;
  gap: 6px;
  padding: 13px;
  border: 1px solid #eaf4ff;
  border-radius: 12px;
  background: #f6fbff;
}

.rms-inspector-operation p,
.rms-inspector-operation small {
  margin: 0;
  color: #53677f;
}

.rms-inspector-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
}

.rms-inspector-move {
  display: grid;
  gap: 6px;
}

.rms-event-log {
  display: grid;
  gap: 9px;
}

.rms-event-item {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 10px;
  border: 1px solid #d8e6f2;
  border-radius: 10px;
  background: #f8fbff;
}

.rms-event-item > .material-symbols-outlined {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  color: #063a9f;
  background: #f6fbff;
}

.rms-event-item strong,
.rms-event-item small {
  display: block;
}

.rms-event-item small,
.rms-event-item time {
  color: #53677f;
}

.rms-event-item time {
  font-size: 0.76rem;
  font-weight: 800;
