/* Portal-wide Infinite Canvas spacing correction */
:root,
:root[data-theme="dark"] {
  --infinite-canvas-base: #f6fbff;
  --infinite-canvas-ink: #052a6b;
  --infinite-canvas-muted: #53677f;
  --infinite-canvas-soft: #53677f;
  --infinite-canvas-line: rgba(5, 42, 107, 0.12);
  --infinite-canvas-faint: rgba(5, 42, 107, 0.07);
  --infinite-canvas-field: rgba(5, 42, 107, 0.16);
  --infinite-canvas-sheet: rgba(255, 255, 255, 0.66);
  --infinite-canvas-soft-sheet: rgba(255, 255, 255, 0.42);
  --infinite-canvas-accent: #0759d6;
  --infinite-canvas-blue: #225f86;
}

html,
body {
  min-height: 100%;
}

body {
  color: var(--infinite-canvas-ink) !important;
  background:
    linear-gradient(90deg, rgba(5, 42, 107, 0.055) 1px, transparent 1px),
    linear-gradient(180deg, rgba(5, 42, 107, 0.045) 1px, transparent 1px),
    linear-gradient(135deg, rgba(5, 42, 107, 0.055) 0%, transparent 28%, rgba(34, 95, 134, 0.05) 68%, transparent 100%),
    var(--infinite-canvas-base) !important;
  background-attachment: fixed !important;
  background-size: 72px 72px, 72px 72px, 100% 100%, auto !important;
}

.portal-shell,
.workspace,
.app-main {
  background: transparent !important;
}

.content-shell {
  width: 100% !important;
  padding: calc(var(--topbar-height) + 42px) clamp(28px, 4.5vw, 76px) 76px !important;
}

.view-section.active {
  max-width: 1540px !important;
  margin: 0 auto 48px !important;
  padding: clamp(26px, 3vw, 46px) !important;
  border: 1px solid var(--infinite-canvas-faint) !important;
  border-radius: 8px !important;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.62), rgba(255, 255, 255, 0.42)),
    linear-gradient(90deg, rgba(5, 42, 107, 0.035), transparent 32%, rgba(34, 95, 134, 0.03)) !important;
  box-shadow: none !important;
  backdrop-filter: blur(6px) !important;
}

.view-head {
  max-width: 1160px !important;
  margin: 0 0 clamp(28px, 3vw, 44px) !important;
  padding: 0 0 24px !important;
  border-bottom: 1px solid var(--infinite-canvas-line) !important;
}

.view-title-block {
  max-width: 900px !important;
}

.view-title-block h1,
.view-head h1,
.section-header h2,
.card-title,
.table-card-head h2 {
  color: var(--infinite-canvas-ink) !important;
  letter-spacing: 0 !important;
}

.view-title-block p,
.view-head p,
.section-header p,
.card-subtitle,
.table-card-head p {
  max-width: 760px !important;
  color: var(--infinite-canvas-muted) !important;
  line-height: 1.62 !important;
}

.cards-grid,
.stats-grid,
.dashboard-grid,
.charts-grid,
.tables-grid,
.insight-grid,
.qr-options-grid,
.campaign-grid,
.activation-dashboard-grid,
.activation-games-grid,
.activation-form-grid,
.activation-play-grid,
.activation-share-grid,
.lead-directory-grid,
.rms-station-grid,
.rms-machine-grid,
.rms-machine-layout,
.rms-station-workspace,
.contact-center-shell,
.agenda-board,
.lead-agenda-board,
.dashboard-builder-layout,
.dashboard-widget-grid,
.campaign-cost-grid,
.competition-grid,
.affiliate-grid,
.account-grid {
  gap: clamp(20px, 2.2vw, 34px) !important;
}

.surface-card,
.data-table-card,
.chart-card,
.map-card,
.insight-card,
.stat-card,
.kpi-card,
.metric-card,
.qr-option-card,
.campaign-card,
.activation-card,
.activation-game-card,
.activation-panel,
.activation-form-panel,
.activation-preview-panel,
.activation-share-panel,
.lead-directory-card,
.lead-detail-card,
.lead-agenda-card,
.agenda-panel,
.table-card,
.inventory-card,
.sales-panel,
.profile-card,
.billing-card,
.account-panel,
.reward-pass-panel,
.modal-card {
  padding: clamp(20px, 2.1vw, 32px) !important;
  border: 1px solid var(--infinite-canvas-faint) !important;
  border-radius: 8px !important;
  background: var(--infinite-canvas-sheet) !important;
  box-shadow: none !important;
}

.dashboard-widget-card,
.dashboard-widget-preview,
.lead-agenda-column,
.lead-agenda-card-item,
.rms-station-lane,
.rms-station-card,
.rms-lead-inspector,
.campaign-cost-section,
.campaign-cost-answer-card,
.campaign-cost-detail-card,
.competition-card,
.affiliate-stat-card,
.affiliate-step,
.season-launch-card,
.qr-workflow-card,
.activation-question-row,
.activation-product-row {
  padding: clamp(16px, 1.7vw, 24px) !important;
  border: 1px solid var(--infinite-canvas-faint) !important;
  border-radius: 8px !important;
  background: var(--infinite-canvas-soft-sheet) !important;
  box-shadow: none !important;
}

.surface-card > .surface-card,
.activation-form-panel .activation-question-row,
.activation-form-panel .activation-product-row,
.lead-agenda-column .lead-agenda-card-item,
.rms-station-lane .rms-station-card {
  background: rgba(255, 255, 255, 0.32) !important;
}

.table-card-head,
.section-header,
.card-header,
.panel-header,
.activation-panel-head,
.rms-station-header,
.lead-directory-header {
  margin: 0 0 22px !important;
  padding: 0 0 18px !important;
  border-bottom: 1px solid var(--infinite-canvas-line) !important;
}

.table-wrap,
.table-responsive,
.lead-table-scroll,
.agenda-table-wrap {
  padding: 0 !important;
  border: 1px solid var(--infinite-canvas-faint) !important;
  border-radius: 8px !important;
  background: rgba(255, 255, 255, 0.34) !important;
  overflow: auto !important;
}

table {
  min-width: 760px !important;
}

thead th,
th {
  padding: 14px 16px !important;
  background: rgba(255, 255, 255, 0.44) !important;
  border-bottom: 1px solid var(--infinite-canvas-line) !important;
}

tbody td,
td {
  padding: 15px 16px !important;
  border-top: 1px solid var(--infinite-canvas-faint) !important;
}

input,
select,
textarea,
.modal-form input,
.modal-form select,
.modal-form textarea,
.view-section input,
.view-section select,
.view-section textarea,
.view-section[data-view="account"] input,
.view-section[data-view="account"] select,
.view-section[data-view="account"] textarea,
.view-section[data-view="affiliates"] input,
.view-section[data-view="affiliates"] select,
.view-section[data-view="affiliates"] textarea,
.view-section[data-view="strategic-qr"] input,
.view-section[data-view="strategic-qr"] select,
.view-section[data-view="strategic-qr"] textarea,
.view-section[data-view="campaigns"] input,
.view-section[data-view="campaigns"] select,
.view-section[data-view="campaigns"] textarea {
  min-height: 44px !important;
  padding: 10px 0 11px !important;
  border-bottom-color: var(--infinite-canvas-field) !important;
  line-height: 1.35 !important;
}

textarea,
.view-section textarea,
.modal-form textarea {
  min-height: 104px !important;
  resize: vertical !important;
}

.modal-form label,
.lead-agenda-create-form label,
.inventory-form label,
.affiliate-form label,
.account-profile-form label,
.reward-pass-form label,
.campaign-form-grid label,
.sales-form label {
  gap: 8px !important;
  padding: 0 0 14px !important;
}

.button-row,
.modal-actions,
.modal-button-row,
.inline-actions,
.activation-share-actions,
.activation-manage-actions,
.qr-batch-actions,
.ticket-status-actions,
.strategic-ticket-actions-cell {
  gap: 12px !important;
  padding-top: 18px !important;
}

.btn,
button,
.nav-item,
.sidebar-nav a {
  letter-spacing: 0 !important;
}

.sidebar {
  padding: 28px 18px !important;
  border-right: 1px solid var(--infinite-canvas-line) !important;
  background: rgba(255, 255, 255, 0.72) !important;
  backdrop-filter: blur(14px) !important;
}

.sidebar-brand {
  margin-bottom: 28px !important;
  padding-bottom: 22px !important;
  border-bottom: 1px solid var(--infinite-canvas-line) !important;
}

.topbar {
  padding-inline: clamp(24px, 3.4vw, 56px) !important;
  border-bottom: 1px solid var(--infinite-canvas-line) !important;
  background: rgba(246, 251, 255, 0.78) !important;
  backdrop-filter: blur(14px) !important;
}

.login-screen {
  padding: clamp(24px, 5vw, 72px) !important;
  background:
    linear-gradient(90deg, rgba(5, 42, 107, 0.055) 1px, transparent 1px),
    linear-gradient(180deg, rgba(5, 42, 107, 0.045) 1px, transparent 1px),
    linear-gradient(135deg, rgba(5, 42, 107, 0.06), transparent 32%, rgba(34, 95, 134, 0.052)),
    var(--infinite-canvas-base) !important;
  background-size: 72px 72px, 72px 72px, 100% 100%, auto !important;
}

.login-card {
  padding: clamp(28px, 4vw, 48px) !important;
  border: 1px solid var(--infinite-canvas-line) !important;
  border-radius: 8px !important;
  background: rgba(255, 255, 255, 0.72) !important;
  box-shadow: none !important;
  backdrop-filter: blur(10px) !important;
}

.empty-state,
.placeholder-card,
.table-empty,
.error-line,
.form-message {
  padding: clamp(16px, 2vw, 24px) !important;
  border: 1px solid var(--infinite-canvas-faint) !important;
  border-left: 2px solid var(--infinite-canvas-accent) !important;
  border-radius: 8px !important;
  background: rgba(255, 255, 255, 0.36) !important;
}

@media (max-width: 1180px) {
  .content-shell {
    padding-inline: clamp(22px, 4vw, 44px) !important;
  }

  .view-section.active {
    padding: clamp(22px, 3.6vw, 34px) !important;
  }
}

@media (max-width: 900px) {
  body,
  .login-screen {
    background-size: 56px 56px, 56px 56px, 100% 100%, auto !important;
  }

  .content-shell {
    padding: calc(var(--topbar-height) + 22px) 16px 42px !important;
  }

  .view-section.active {
    margin-bottom: 28px !important;
    padding: 18px !important;
  }

  .surface-card,
  .data-table-card,
  .chart-card,
  .map-card,
  .insight-card,
  .stat-card,
  .kpi-card,
  .metric-card,
  .activation-card,
  .activation-panel,
  .activation-form-panel,
  .activation-preview-panel,
  .lead-directory-card,
  .lead-detail-card,
  .lead-agenda-card,
  .agenda-panel,
  .table-card,
  .inventory-card,
  .sales-panel,
  .profile-card,
  .billing-card,
  .account-panel,
  .reward-pass-panel,
  .modal-card {
    padding: 18px !important;
  }

  .topbar {
    padding-inline: 16px !important;
  }
}

/* Guided friendly canvas and collapsible operating zones */
:root,
:root[data-theme="dark"] {
  --guided-canvas-mint: #f6fbff;
  --guided-canvas-sage: #eaf4ff;
  --guided-canvas-white: #fffefa;
  --guided-canvas-blue: #e7f3fb;
  --guided-canvas-blue-line: rgba(39, 117, 159, 0.13);
  --guided-canvas-green-line: rgba(7, 89, 214, 0.13);
  --guided-canvas-ink: #052a6b;
  --guided-canvas-muted: #53677f;
  --guided-canvas-soft: #53677f;
  --guided-canvas-accent: #0759d6;
  --guided-canvas-accent-2: #0759d6;
  --guided-canvas-panel: rgba(246, 251, 255, 0.72);
  --guided-canvas-panel-soft: rgba(246, 251, 255, 0.52);
}

body {
  color: var(--guided-canvas-ink) !important;
  background:
    linear-gradient(90deg, rgba(7, 89, 214, 0.055) 1px, transparent 1px),
    linear-gradient(180deg, rgba(39, 117, 159, 0.05) 1px, transparent 1px),
    linear-gradient(120deg, rgba(246, 251, 255, 0.92) 0%, rgba(255, 254, 250, 0.9) 34%, rgba(231, 243, 251, 0.78) 68%, rgba(246, 251, 255, 0.92) 100%),
    var(--guided-canvas-mint) !important;
  background-size: 78px 78px, 78px 78px, 100% 100%, auto !important;
  background-attachment: fixed !important;
}

.view-section.active {
  border-color: rgba(7, 89, 214, 0.1) !important;
  background:
    linear-gradient(180deg, rgba(255, 254, 250, 0.7), rgba(255, 254, 250, 0.5)),
    linear-gradient(90deg, rgba(246, 251, 255, 0.62), rgba(231, 243, 251, 0.42) 76%, rgba(255, 254, 250, 0.56)) !important;
}

.surface-card,
.data-table-card,
.chart-card,
.map-card,
.insight-card,
.stat-card,
.kpi-card,
.metric-card,
.qr-option-card,
.campaign-card,
.activation-card,
.activation-game-card,
.activation-panel,
.activation-form-panel,
.activation-preview-panel,
.activation-share-panel,
.lead-directory-card,
.lead-detail-card,
.lead-agenda-card,
.agenda-panel,
.table-card,
.inventory-card,
.sales-panel,
.profile-card,
.billing-card,
.account-panel,
.reward-pass-panel,
.modal-card {
  border-color: rgba(7, 89, 214, 0.1) !important;
  background:
    linear-gradient(180deg, rgba(255, 254, 250, 0.74), rgba(255, 254, 250, 0.56)),
    linear-gradient(90deg, rgba(246, 251, 255, 0.22), rgba(231, 243, 251, 0.18)) !important;
}

.dashboard-widget-card,
.dashboard-widget-preview,
.lead-agenda-column,
.lead-agenda-card-item,
.rms-station-lane,
.rms-station-card,
.rms-lead-inspector,
.campaign-cost-section,
.campaign-cost-answer-card,
.campaign-cost-detail-card,
.competition-card,
.affiliate-stat-card,
.affiliate-step,
.season-launch-card,
.qr-workflow-card,
.activation-question-row,
.activation-product-row,
.activation-form-field-row,
.trivia-question-editor {
  border-color: rgba(39, 117, 159, 0.11) !important;
  background:
    linear-gradient(180deg, rgba(255, 254, 250, 0.58), rgba(255, 254, 250, 0.42)),
    linear-gradient(90deg, rgba(246, 251, 255, 0.22), rgba(231, 243, 251, 0.16)) !important;
}

.topbar,
.sidebar,
.login-card {
  background: rgba(255, 254, 250, 0.76) !important;
}

.search-shell,
.subscription-banner,
.gaming-core-entry {
  border-color: rgba(39, 117, 159, 0.12) !important;
  background:
    linear-gradient(90deg, rgba(246, 251, 255, 0.7), rgba(231, 243, 251, 0.46)),
    rgba(255, 254, 250, 0.58) !important;
}

.quiet-zone {
  position: relative !important;
  transition: background-color 160ms ease, border-color 160ms ease !important;
}

.quiet-zone-control-head {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) auto !important;
  align-items: start !important;
  gap: 16px !important;
}

.quiet-zone-toggle {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 7px !important;
  min-height: 34px !important;
  padding: 7px 10px !important;
  border: 1px solid rgba(39, 117, 159, 0.16) !important;
  border-radius: 999px !important;
  background: rgba(255, 254, 250, 0.7) !important;
  color: var(--guided-canvas-muted) !important;
  box-shadow: none !important;
  font-size: 0.78rem !important;
  font-weight: 760 !important;
  line-height: 1 !important;
  white-space: nowrap !important;
}

.quiet-zone-toggle:hover,
.quiet-zone-toggle:focus-visible {
  border-color: rgba(7, 89, 214, 0.28) !important;
  color: var(--guided-canvas-accent) !important;
  background: rgba(246, 251, 255, 0.88) !important;
}

.quiet-zone-toggle .material-symbols-outlined {
  font-size: 1rem !important;
  line-height: 1 !important;
}

.quiet-zone.is-collapsed {
  padding-block: clamp(14px, 1.6vw, 20px) !important;
  border-color: rgba(39, 117, 159, 0.1) !important;
  background:
    linear-gradient(90deg, rgba(246, 251, 255, 0.48), rgba(231, 243, 251, 0.32)),
    rgba(255, 254, 250, 0.46) !important;
}

.quiet-zone.is-collapsed > :not(.quiet-zone-control-head) {
  display: none !important;
}

.quiet-zone.is-collapsed .quiet-zone-control-head {
  margin-bottom: 0 !important;
  padding-bottom: 0 !important;
  border-bottom-color: transparent !important;
}

.action-feedback {
  right: clamp(16px, 3vw, 42px) !important;
  bottom: clamp(16px, 3vw, 36px) !important;
  max-width: min(420px, calc(100vw - 32px)) !important;
  border: 1px solid rgba(7, 89, 214, 0.16) !important;
  background: rgba(255, 254, 250, 0.86) !important;
  color: var(--guided-canvas-ink) !important;
  box-shadow: 0 18px 50px rgba(5, 42, 107, 0.08) !important;
  backdrop-filter: blur(14px) !important;
}

.action-feedback.info {
  border-color: rgba(39, 117, 159, 0.18) !important;
}

.action-feedback strong {
  color: var(--guided-canvas-ink) !important;
}

.action-feedback p {
  color: var(--guided-canvas-muted) !important;
}

input:focus,
select:focus,
textarea:focus,
.modal-form input:focus,
.modal-form select:focus,
.modal-form textarea:focus,
.view-section input:focus,
.view-section select:focus,
.view-section textarea:focus {
  border-bottom-color: var(--guided-canvas-accent-2) !important;
  box-shadow: 0 1px 0 var(--guided-canvas-accent-2) !important;
}

tbody tr:hover,
.activation-type-option:hover,
.nav-item:hover {
  background: rgba(246, 251, 255, 0.62) !important;
}

@media (max-width: 900px) {
  body,
  .login-screen {
    background-size: 58px 58px, 58px 58px, 100% 100%, auto !important;
  }

  .quiet-zone-control-head {
    grid-template-columns: 1fr !important;
    gap: 12px !important;
  }

  .quiet-zone-toggle {
    width: fit-content !important;
  }
}

/* Spacious location-aware portal refinement */
:root,
:root[data-theme="dark"] {
  --spacious-bg-a: #f6fbff;
  --spacious-bg-b: #fffefa;
  --spacious-bg-c: #eaf5fb;
  --spacious-bg-d: #f6fbff;
  --spacious-surface-green: rgba(246, 251, 255, 0.78);
  --spacious-surface-blue: rgba(235, 247, 253, 0.74);
  --spacious-surface-white: rgba(255, 254, 250, 0.82);
  --spacious-surface-sage: rgba(246, 251, 255, 0.7);
  --spacious-line: rgba(5, 42, 107, 0.14);
  --spacious-line-blue: rgba(42, 103, 139, 0.16);
  --spacious-active: #052a6b;
  --spacious-active-blue: #1f6f98;
  --spacious-ink: #052a6b;
  --spacious-muted: #53677f;
}

body {
  background:
    linear-gradient(90deg, rgba(5, 42, 107, 0.05) 1px, transparent 1px),
    linear-gradient(180deg, rgba(31, 111, 152, 0.045) 1px, transparent 1px),
    linear-gradient(145deg, var(--spacious-bg-a) 0%, var(--spacious-bg-b) 33%, var(--spacious-bg-c) 66%, var(--spacious-bg-d) 100%) !important;
  background-size: 86px 86px, 86px 86px, 100% 100% !important;
  background-attachment: fixed !important;
}

.content-shell {
  padding: calc(var(--topbar-height) + 56px) clamp(42px, 5vw, 96px) 96px !important;
}

.view-section.active {
  max-width: 1500px !important;
  margin: 0 auto 64px !important;
  padding: clamp(34px, 3.8vw, 60px) !important;
  border: 1px solid rgba(5, 42, 107, 0.12) !important;
  background:
    linear-gradient(180deg, rgba(255, 254, 250, 0.68), rgba(255, 254, 250, 0.5)),
    linear-gradient(110deg, rgba(246, 251, 255, 0.76), rgba(235, 247, 253, 0.5) 58%, rgba(255, 254, 250, 0.68)) !important;
}

.view-section.active > * + * {
  margin-top: clamp(28px, 3vw, 46px) !important;
}

.view-head {
  max-width: none !important;
  margin-bottom: clamp(34px, 3.5vw, 54px) !important;
  padding-bottom: 26px !important;
}

.portal-location-pill {
  display: inline-flex !important;
  align-items: center !important;
  gap: 8px !important;
  width: fit-content !important;
  margin: 0 0 20px !important;
  padding: 8px 12px !important;
  border: 1px solid rgba(31, 111, 152, 0.16) !important;
  border-radius: 999px !important;
  background:
    linear-gradient(90deg, rgba(246, 251, 255, 0.92), rgba(235, 247, 253, 0.76)),
    rgba(255, 254, 250, 0.82) !important;
  color: var(--spacious-muted) !important;
  font-size: 0.82rem !important;
  line-height: 1.2 !important;
}

.portal-location-pill .material-symbols-outlined {
  color: var(--spacious-active-blue) !important;
  font-size: 1rem !important;
}

.portal-location-pill strong {
  color: var(--spacious-active) !important;
}

.portal-location-pill span:last-child {
  color: var(--spacious-ink) !important;
  font-weight: 760 !important;
}

.surface-card,
.data-table-card,
.chart-card,
.map-card,
.insight-card,
.stat-card,
.kpi-card,
.metric-card,
.qr-option-card,
.campaign-card,
.activation-card,
.activation-game-card,
.activation-panel,
.activation-form-panel,
.activation-preview-panel,
.activation-share-panel,
.lead-directory-card,
.lead-detail-card,
.lead-agenda-card,
.agenda-panel,
.table-card,
.inventory-card,
.sales-panel,
.profile-card,
.billing-card,
.account-panel,
.reward-pass-panel,
.modal-card,
.quiet-zone {
  padding: clamp(24px, 2.4vw, 38px) !important;
