  --qori-page-max: 1500px;
  --qori-page-pad: clamp(24px, 3.2vw, 48px);
  --qori-block-gap: clamp(22px, 2.4vw, 34px);
  --qori-inner-gap: clamp(14px, 1.6vw, 22px);
  --qori-line: rgba(5, 42, 107, 0.12);
  --qori-line-soft: rgba(5, 42, 107, 0.075);
  --qori-ink: #052a6b;
  --qori-muted: #53677f;
  --qori-blue: #0759d6;
  --qori-cyan: #00bfe5;
  --qori-sheet: rgba(255, 254, 250, 0.86);
  --qori-soft-sheet: rgba(246, 251, 255, 0.72);
